function _sid(dirName, scriptName, flag) {
  return 'sopt-'+dirName+'-'+scriptName+'-'+flag.replace(/[^a-zA-Z0-9]/g,'');
}
function renderScriptModule(s, dirName) {
  var mod = _scriptModules[s.name];
  var icon = mod ? mod.icon : '📜';
  var desc = mod ? mod.desc : (s.scope+' script');
  var sn = s.name.replace(/[^a-zA-Z0-9]/g,'');
  var hasOpts = mod && mod.opts && mod.opts.some(function(o){return o.t!=='h';});
  var h = '<div style="border:1px solid var(--bdr);border-radius:8px;margin-bottom:6px;overflow:hidden">';
  h += '<div style="display:flex;align-items:center;gap:10px;padding:10px 12px;cursor:pointer" onclick="toggleScriptMod(\''+dirName+'\',\''+s.name+'\')">';
  h += '<span style="font-size:18px">'+icon+'</span>';
  h += '<div style="flex:1;min-width:0"><div style="font-size:13px;font-weight:500">'+s.name+'.php</div>';
  h += '<div style="font-size:11px;color:var(--dim)">'+desc+'</div></div>';
  h += '<span style="font-size:10px;padding:2px 6px;border-radius:3px;background:rgba(255,255,255,.06);color:var(--dim)">'+s.scope+'</span>';
  h += '<span id="smod-chev-'+dirName+'-'+sn+'" style="font-size:10px;color:var(--dim);transition:transform .2s">▶</span>';
  h += '</div>';
  h += '<div id="smod-body-'+dirName+'-'+sn+'" style="display:none;padding:0 12px 12px;border-top:1px solid var(--bdr)">';
  if (hasOpts) {
    h += '<div style="margin-top:8px">';
    mod.opts.forEach(function(opt) {
      if (opt.t==='h') {
        h += '<div style="font-size:10px;font-weight:600;text-transform:uppercase;color:var(--dim);margin:10px 0 4px;letter-spacing:.5px">'+opt.label+'</div>';
        return;
      }
      var id = _sid(dirName, s.name, opt.f);
      if (opt.t==='c') {
        h += '<label style="display:flex;align-items:center;gap:6px;font-size:12px;padding:3px 0;cursor:pointer">'
          + '<input type="checkbox" id="'+id+'"> '+opt.l+'</label>';
      } else if (opt.t==='x') {
        h += '<div style="display:flex;align-items:center;gap:8px;padding:3px 0">'
          + '<label style="font-size:12px;min-width:110px;color:var(--dim)" for="'+id+'">'+opt.l+'</label>'
          + '<input type="text" id="'+id+'" placeholder="'+(opt.p||'')+'" style="flex:1;font-size:12px;padding:4px 8px;background:rgba(0,0,0,.2);border:1px solid var(--bdr);border-radius:4px;color:var(--fg)">'
          + '</div>';
      } else if (opt.t==='s') {
        h += '<div style="display:flex;align-items:center;gap:8px;padding:3px 0">'
          + '<label style="font-size:12px;min-width:110px;color:var(--dim)" for="'+id+'">'+opt.l+'</label>'
          + '<select id="'+id+'" style="flex:1;font-size:12px;padding:4px 8px;background:rgba(0,0,0,.2);border:1px solid var(--bdr);border-radius:4px;color:var(--fg)">'
          + '<option value="">—</option>';
        (opt.o||[]).forEach(function(o){ h += '<option value="'+o.v+'">'+o.l+'</option>'; });
        h += '</select></div>';
      }
    });
    h += '</div>';
  }
  h += '<div style="margin-top:10px;display:flex;gap:8px;align-items:center">'
    + '<button class="btn btn-sm" id="smod-run-'+dirName+'-'+sn+'" onclick="runScriptModule(\''+dirName+'\',\''+s.name+'\',this)" style="font-size:12px;padding:5px 14px">▶ Run</button>'
    + '<span id="smod-st-'+dirName+'-'+sn+'" style="font-size:11px;color:var(--dim)"></span>'
    + '</div>';
  h += '<pre id="smod-out-'+dirName+'-'+sn+'" style="display:none;max-height:400px;overflow:auto;font-size:11px;padding:10px;background:rgba(0,0,0,.3);border-radius:6px;white-space:pre-wrap;word-break:break-all;margin-top:8px"></pre>';
  h += '</div></div>';
  return h;
}
function toggleScriptMod(dirName, scriptName) {
  var sn = scriptName.replace(/[^a-zA-Z0-9]/g,'');
  var body = document.getElementById('smod-body-'+dirName+'-'+sn);
  var chev = document.getElementById('smod-chev-'+dirName+'-'+sn);
  if (!body) return;
  var show = body.style.display === 'none';
  body.style.display = show ? 'block' : 'none';
  if (chev) chev.textContent = show ? '▼' : '▶';
}
function collectScriptArgs(scriptName, dirName) {
  var mod = _scriptModules[scriptName];
  if (!mod || !mod.opts) return [];
  var args = [];
  mod.opts.forEach(function(opt) {
    if (opt.t === 'h') return;
    var el = document.getElementById(_sid(dirName, scriptName, opt.f));
    if (!el) return;
    if (opt.t === 'c') {
      if (el.checked) args.push(opt.f);
    } else if (opt.t === 's') {
      var v = el.value;
      if (!v) return;
      if (opt.f.charAt(0) === '_') { args.push(v); } // value IS the flag
      else { args.push(opt.f, v); }
    } else if (opt.t === 'x') {
      var v = el.value.trim();
      if (!v) return;
      if (opt.f.charAt(0) === '_') { args.push(v); } // positional arg
      else { args.push(opt.f, v); }
    }
  });
  return args;
}
async function loadDetailScripts(dirName) {
  var pane = document.getElementById('detail-scripts-'+dirName);
  if (!pane) return;
  pane.innerHTML = '<p style="color:var(--dim);font-size:12px">Loading scripts…</p>';
  try {
    var r = await api('scripts', {app:dirName});
    if (r.error) { pane.innerHTML='<p style="color:var(--red)">'+escHtml(r.error)+'</p>'; return; }
    var scripts = r.scripts || [];
    if (!scripts.length) {
      pane.innerHTML='<p style="color:var(--dim);font-size:12px">No scripts found in scripts/Q/ directory.</p>';
      return;
    }
    var html = '<div style="margin-top:8px">';
    scripts.forEach(function(s) { html += renderScriptModule(s, dirName); });
    html += '</div>';
    pane.innerHTML = html;
  } catch(e) { pane.innerHTML='<p style="color:var(--red)">'+escHtml(e.message)+'</p>'; }
}
async function runScriptModule(dirName, scriptName, btn) {
  var args = collectScriptArgs(scriptName, dirName);
  var sn = scriptName.replace(/[^a-zA-Z0-9]/g,'');
  var out = document.getElementById('smod-out-'+dirName+'-'+sn);
  var st = document.getElementById('smod-st-'+dirName+'-'+sn);
  if (out) { out.style.display='block'; out.textContent='Running '+scriptName+'.php…\n'; out.style.color='var(--fg)'; }
  if (st) { st.textContent='Running…'; st.style.color='var(--dim)'; }
  if (btn) { btn.disabled=true; btn.textContent='⏳'; }
  try {
    var r = await api('scripts/run', {app:dirName, script:scriptName, args:args});
    if (r.error) {
      if (out) { out.textContent += '⚠ Error: '+r.error; out.style.color='var(--red)'; }
      if (st) { st.textContent='Error'; st.style.color='var(--red)'; }
    } else {
      var cmdStr = 'php scripts/Q/'+scriptName+'.php'+(args.length ? ' '+args.join(' ') : '');
      if (out) {
        var rawOut = r.output || '(no output)';
        out.innerHTML = escHtml('$ '+cmdStr) + '\n\n' + ansiToHtml(rawOut) + '\n\n' + escHtml('Exit code: '+r.exitCode);
        out.style.color = r.exitCode === 0 ? 'var(--grn)' : 'var(--yel)';
      }
      if (st) {
        st.textContent = r.exitCode === 0 ? 'Done ✓' : 'Exit '+r.exitCode;
        st.style.color = r.exitCode === 0 ? 'var(--grn)' : 'var(--yel)';
      }
    }
  } catch(e) {
    if (out) { out.textContent += 'Error: '+e.message; out.style.color='var(--red)'; }
    if (st) { st.textContent='Error'; st.style.color='var(--red)'; }
  }
  if (btn) { btn.disabled=false; btn.textContent='▶ Run'; }
  if (out) out.scrollTop = out.scrollHeight;
}
// Legacy — still used by Actions tab
async function runAppScript(dirName, scriptName, btn) {
  runScriptModule(dirName, scriptName, btn);
}
// Put a chart tooltip next to the pointer, but never outside the box it floats in (it used to be cut off at the bottom)
function qTipPlace(tip, ev) {
  var p = tip.offsetParent || tip.parentNode;
  var r = p.getBoundingClientRect();
  var w = tip.offsetWidth, h = tip.offsetHeight, pw = p.clientWidth, ph = p.clientHeight;
  var px = ev.clientX - r.left, py = ev.clientY - r.top;
  var x = px + 14, y = py + 14;
  if (x + w > pw - 4) x = px - w - 14;
  if (y + h > ph - 4) y = py - h - 14;
  x = Math.max(4, Math.min(x, pw - w - 4));
  y = Math.max(4, Math.min(y, ph - h - 4));
  tip.style.left = (x + (p.scrollLeft || 0)) + 'px';
  tip.style.top = y + 'px';
}
// Text areas grow to show their text, up to half the window, and shrink again
function qGrow(t) {
  if (!t || t.tagName !== 'TEXTAREA' || t.offsetParent === null) return;
  var max = Math.floor(window.innerHeight * 0.5);
  t.style.height = 'auto';
  var want = t.scrollHeight + 2;
  t.style.height = Math.min(want, max) + 'px';
  t.style.overflowY = want > max ? 'auto' : 'hidden';
}
document.addEventListener('input', function(e) { qGrow(e.target); });
document.addEventListener('focusin', function(e) { qGrow(e.target); });
window.addEventListener('resize', function() { document.querySelectorAll('textarea').forEach(qGrow); });
// Values set by code, tabs shown later, and fields added to the page: look again now and then
setInterval(function() {
  document.querySelectorAll('textarea').forEach(function(t) {
    if (t.offsetParent !== null && (t.scrollHeight > t.clientHeight + 2 || t.dataset.qg !== String(t.value.length))) {
      t.dataset.qg = String(t.value.length);
      qGrow(t);
    }
  });
}, 1200);
// A dialog in the page (alert() cannot hold a long error and is not copyable)
function showDialog(title, bodyHtml, buttons) {
  var ov = document.createElement('div');
  ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.6);z-index:300;display:flex;align-items:center;justify-content:center;padding:16px';
  var box = document.createElement('div');
  box.style.cssText = 'background:var(--sfc-solid);border:1px solid var(--brd);border-radius:10px;max-width:720px;width:100%;max-height:85vh;display:flex;flex-direction:column;box-shadow:0 10px 40px rgba(0,0,0,.5)';
  box.innerHTML = '<div style="padding:14px 16px;border-bottom:1px solid var(--brd);font-weight:600">' + escHtml(title) + '</div>'
    + '<div style="padding:14px 16px;overflow:auto;font-size:13px">' + bodyHtml + '</div>'
    + '<div class="dlg-btns" style="padding:10px 16px;border-top:1px solid var(--brd);display:flex;gap:8px;justify-content:flex-end;flex-wrap:wrap"></div>';
  var bar = box.querySelector('.dlg-btns');
  (buttons || [{label: 'Close'}]).forEach(function(b) {
    var el = document.createElement('button');
    el.className = 'btn ' + (b.primary ? 'btn-primary' : 'btn-ghost');
    el.textContent = b.label;
    el.onclick = function() { ov.remove(); if (b.action) b.action(); };
    bar.appendChild(el);
  });
  ov.appendChild(box);
  ov.addEventListener('click', function(e) { if (e.target === ov) ov.remove(); });
  document.body.appendChild(ov);
  return ov;
}
// Why a certificate request failed, with a way to copy the text and to try again
function showCertError(name, error, at, via, retry) {
  var when = at ? ' <span style="color:var(--dim)">(' + escHtml(String(at).replace('T', ' ').replace('Z', ' UTC')) + ')</span>' : '';
  var how = via === 'certbot' ? ' through certbot and nginx' : '';
  showDialog('Certificate for ' + name + ' failed', '<p style="margin:0 0 8px">The request' + how + ' did not finish' + when + '.</p>'
    + '<pre style="white-space:pre-wrap;word-break:break-word;background:rgba(0,0,0,.25);padding:10px;border-radius:6px;font-size:12px;margin:0;user-select:all">' + escHtml(error) + '</pre>'
    + '<p style="color:var(--dim);font-size:12px;margin:10px 0 0">Common causes: the name does not point at this server yet, port 80 is not reachable from the internet, certbot or nginx is missing or needs sudo, or Let\'s Encrypt rate limits were hit. Fix it and try again.</p>',
    [{label: 'Copy', action: function() { try { navigator.clipboard.writeText(error); } catch (e) {} }}, {label: 'Close'}, {label: 'Try again', primary: true, action: retry}]);
}
var _certErr = {};
function showCertErrorKey(k) {
  var c = _certErr[k]; if (!c) return;
  showCertError(c.name, c.error, c.at, c.via, c.retry);
}
function showToast(msg, duration) {
  var el = document.createElement('div');
  el.textContent = msg;
  el.style.cssText = 'position:fixed;bottom:24px;left:50%;transform:translateX(-50%);background:var(--ac);color:#fff;padding:8px 20px;border-radius:8px;font-size:13px;z-index:200;opacity:0;transition:opacity .3s';
  document.body.appendChild(el);
  requestAnimationFrame(function(){el.style.opacity='1'});
  setTimeout(function(){el.style.opacity='0';setTimeout(function(){el.remove()},300)}, duration||3000);
}
function escHtml(s) {
  var d = document.createElement('div');
  d.textContent = s;
  return d.innerHTML;
}
function escAttr(s) {
  return String(s).replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/'/g,'&#39;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}
function ansiToHtml(s) {
  // Strip cursor-movement codes (e.g. ESC[100D, ESC[K, ESC[2J)
  s = s.replace(/\x1b\[\d*[A-HJKSTfm]|\x1b\[\d+;\d+[Hf]|\x1b\[\?[0-9;]*[hlr]|\x1b\[[\d;]*[su]|\r/g, function(m) {
    if (/m$/.test(m)) return m; // keep SGR (color) codes
    return ''; // strip everything else
  });
  // Escape HTML
  s = escHtml(s);
  // Convert SGR color codes to spans
  var colorMap = {30:'#555',31:'#e55',32:'#5e5',33:'#ee5',34:'#55e',35:'#e5e',36:'#5ee',37:'#eee',
    90:'#888',91:'#f88',92:'#8f8',93:'#ff8',94:'#88f',95:'#f8f',96:'#8ff',97:'#fff'};
  var open = 0;
  s = s.replace(/\x1b\[([\d;]*)m/g, function(_, codes) {
    if (!codes || codes === '0') {
      var cls = '';
      while (open > 0) { cls += '</span>'; open--; }
      return cls;
    }
    var parts = codes.split(';');
    var style = '';
    for (var i = 0; i < parts.length; i++) {
      var c = parseInt(parts[i], 10);
      if (c === 1) style += 'font-weight:bold;';
      else if (c === 2) style += 'opacity:.6;';
      else if (c === 3) style += 'font-style:italic;';
      else if (c === 4) style += 'text-decoration:underline;';
      else if (colorMap[c]) style += 'color:' + colorMap[c] + ';';
      else if (c >= 40 && c <= 47) style += 'background:' + (colorMap[c - 10] || '') + ';';
      else if (c >= 100 && c <= 107) style += 'background:' + (colorMap[c - 60] || '') + ';';
    }
    if (style) { open++; return '<span style="' + style + '">'; }
    return '';
  });
  while (open > 0) { s += '</span>'; open--; }
  return s;
}

async function showCreate() {
  document.getElementById('create-form').classList.remove('hidden');
  // Populate templates dynamically
  var sel = document.getElementById('new-template');
  sel.innerHTML = '<option value="">(blank app)</option>';
  try {
    var r = await api('apps/templates');
    if (r.templates && r.templates.length) {
      r.templates.forEach(function(t) {
        var opt = document.createElement('option');
        opt.value = t;
        opt.textContent = t;
        sel.appendChild(opt);
      });
    }
  } catch(e) { /* silently ignore — blank app still works */ }
}
function hideCreate(){document.getElementById('create-form').classList.add('hidden')}

// ── App Config (local/app.json) ──────────────────────
async function loadAppConfig(dirName, branchName) {
  var paneId = branchName ? 'detail-branchconfig-'+dirName+'-'+branchName : 'detail-config-'+dirName;
  var pane = document.getElementById(paneId);
  if (!pane) return;
  pane.innerHTML = '<p style="color:var(--dim);font-size:12px">Loading config…</p>';
  var params = 'app=' + encodeURIComponent(dirName);
  if (branchName) params += '&branch=' + encodeURIComponent(branchName);
  try {
    var r = await api('apps/config?' + params);
    if (r.error) { pane.innerHTML = '<p style="color:var(--red)">' + escHtml(r.error) + '</p>'; return; }
    var pretty = '';
    try { pretty = JSON.stringify(JSON.parse(r.config), null, 2); } catch(e) { pretty = r.config || '{}'; }
    pane.innerHTML =
      '<div style="margin-bottom:8px;font-size:12px;color:var(--dim)">Path: ' + escHtml(r.path) + '</div>'
      + '<textarea id="app-config-textarea-'+escAttr(dirName)+(branchName?'-'+escAttr(branchName):'')+'" style="width:100%;min-height:200px;font-family:monospace;font-size:12px;background:var(--card);color:var(--fg);border:1px solid var(--bdr);border-radius:6px;padding:8px;box-sizing:border-box;resize:vertical">'
      + escHtml(pretty) + '</textarea>'
      + '<div style="margin-top:8px;display:flex;gap:8px">'
      + '<button class="btn btn-primary btn-sm" onclick="saveAppConfig(\'' + escAttr(dirName) + '\''+(branchName?',\''+escAttr(branchName)+'\'':',null')+')" style="font-size:12px">Save</button>'
      + '<span id="app-config-status-'+escAttr(dirName)+(branchName?'-'+escAttr(branchName):'')+'"></span>'
      + '</div>';
  } catch(e) { pane.innerHTML = '<p style="color:var(--red)">'+escHtml(e.message)+'</p>'; }
}

async function saveAppConfig(dirName, branchName) {
  var taId = 'app-config-textarea-' + dirName + (branchName ? '-' + branchName : '');
  var stId = 'app-config-status-' + dirName + (branchName ? '-' + branchName : '');
  var ta = document.getElementById(taId);
  var st = document.getElementById(stId);
  if (!ta) return;
  var raw = ta.value;
  try { JSON.parse(raw); } catch(e) {
    if (st) { st.textContent = 'Invalid JSON: ' + e.message; st.style.color = 'var(--red)'; }
    return;
  }
  var body = { app: dirName, config: raw };
  if (branchName) body.branch = branchName;
  try {
    var r = await api('apps/config/update', body);
    if (r.error) {
      if (st) { st.textContent = r.error; st.style.color = 'var(--red)'; }
    } else {
      if (st) { st.textContent = 'Saved.'; st.style.color = 'var(--green)'; }
      setTimeout(function(){ if(st) st.textContent=''; }, 3000);
    }
  } catch(e) {
    if (st) { st.textContent = e.message; st.style.color = 'var(--red)'; }
  }
}

function showBranchConfigInline(dirName, branchName, btn) {
  var paneId = 'detail-branchconfig-' + dirName + '-' + branchName;
  var pane = document.getElementById(paneId);
  if (!pane) return;
  if (pane.style.display === 'none' || pane.style.display === '') {
    pane.style.display = 'block';
    loadAppConfig(dirName, branchName);
  } else {
    pane.style.display = 'none';
  }
}

async function setForkMode(app, value) {
  var forkVal = value === 'true' ? true : (value === 'false' ? false : null);
  var r = await api('apps/fork-mode', {app: app, forkPerRequest: forkVal});
  if (r.note) {
    var out = document.getElementById('fw-output-' + app) || null;
    if (!out) alert(r.note);
  }
  loadApps();
}
async function createApp() {
  var name = document.getElementById('new-name').value.trim();
  var template = document.getElementById('new-template').value;
  if (!name) return alert('Enter an app name');
  var r = await api('apps/create', {name:name, template:template});
  if (r.error) return alert(r.error);
  hideCreate();
  loadApps();
}
// ── Which app a domain serves ──
// One dropdown per domain: the domain's current app first, then apps that serve some domain already
// (they can serve several), then the rest. An app can be chosen for any number of domains.
function domainAppPicker(d) {
  var cur = d.appDir || '';
  var apps = (_appsData || []).filter(function(a) { return a.hasWeb || a.dirName === cur; });
  function rank(a) { return a.dirName === cur ? 0 : ((a.domains && a.domains.length) ? 1 : 2); }
  apps.sort(function(x, y) { return rank(x) - rank(y) || String(x.name).localeCompare(String(y.name)); });
  var o = '<option value=""' + (!cur ? ' selected' : '') + '>No app (welcome page)</option>';
  apps.forEach(function(a) {
    var also = (a.domains || []).filter(function(x) { return x !== d.domain; });
    var label = (a.dirName === cur ? '✓ ' : '') + a.name
      + (also.length ? '  · also ' + also.slice(0, 2).join(', ') + (also.length > 2 ? '…' : '') : '');
    o += '<option value="' + escAttr(a.dirName) + '"' + (a.dirName === cur ? ' selected' : '') + '>' + escHtml(label) + '</option>';
  });
  return '<select class="app-picker" title="Which app this domain serves" onclick="event.stopPropagation()" '
    + 'onchange="setDomainApp(\'' + escAttr(d.domain) + '\', this.value)" '
    + 'style="font-size:12px;padding:3px 8px;max-width:260px;background:var(--card);color:var(--fg);border:1px solid '
    + (cur ? 'var(--ac)' : 'var(--brd)') + ';border-radius:6px">' + o + '</select>';
}
async function setDomainApp(domain, app) {
  var r = await api('domains/set-app', {domain: domain, app: app});
  if (r.error) alert(r.error);
  try { var ar = await api('apps'); if (ar && ar.apps) _appsData = ar.apps; } catch (e) { /* keep what we have */ }
  loadDomains();
  var body = document.getElementById('app-domains-body');
  if (body && _appDomainsFor) await fillAppDomains(_appDomainsFor);
}
var _appDomainsFor = null;
async function fillAppDomains(dirName) {
  var body = document.getElementById('app-domains-body');
  if (!body) return;
  var a = _appsData.find(function(x) { return x.dirName === dirName; });
  if (!a) return;
  var r = await api('domains');
  var all = r.domains || [];
  var mine = (a.domains || []).slice().sort(function(x, y) { return (y === location.hostname ? 1 : 0) - (x === location.hostname ? 1 : 0); });
  var html = mine.length ? mine.map(function(dn) {
    return '<div class="card" style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:6px;padding:8px 12px'
      + (dn === location.hostname ? ';outline:2px solid var(--ac);outline-offset:-2px' : '') + '">'
      + '<strong style="min-width:0;word-break:break-all">' + escHtml(dn) + '</strong>'
      + (dn === location.hostname ? '<span style="font-size:11px;color:var(--ac)">← you are here</span>' : '')
      + '<span style="margin-left:auto">' + domainAppPicker({domain: dn, appDir: dirName}) + '</span></div>';
  }).join('') : '<p style="color:var(--dim);font-size:12px">This app is not served on any domain yet.</p>';
  var others = all.filter(function(d) { return d.appDir !== dirName && !d.unconfigured; })
    .sort(function(x, y) { return (y.domain === location.hostname ? 1 : 0) - (x.domain === location.hostname ? 1 : 0); });
  if (others.length) {
    var names = {};
    _appsData.forEach(function(x) { names[x.dirName] = x.name; });
    html += '<div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:12px">'
      + '<select id="app-add-domain" onchange="document.getElementById(\'app-add-btn\').disabled=!this.value" style="font-size:12px;padding:3px 8px;background:var(--card);color:var(--fg);border:1px solid var(--brd);border-radius:6px;max-width:260px">'
      + '<option value="" disabled selected>' + escHtml(t('Select another domain')) + '</option>'
      + others.map(function(d) {
          return '<option value="' + escAttr(d.domain) + '">' + escHtml(d.domain) + (d.appDir && names[d.appDir] ? ' (' + escHtml(t('now {app}', {app: names[d.appDir]})) + ')' : '') + '</option>';
        }).join('')
      + '</select><button id="app-add-btn" disabled class="btn btn-primary btn-sm" title="' + escAttr(t('Make the chosen domain show this app')) + '" onclick="addDomainToApp(\'' + escAttr(dirName) + '\')">' + escHtml(t('Serve this app there')) + '</button></div>';
  }
  html += '<div style="margin-top:14px"><button class="btn btn-ghost btn-sm" onclick="showTab(\'domains\', {})">🌐 Open Domains</button></div>';
  body.innerHTML = html;
}
async function addDomainToApp(dirName) {
  var sel = document.getElementById('app-add-domain');
  if (!sel || !sel.value) return;
  await setDomainApp(sel.value, dirName);
}
function showAppDomains(dirName) { showAppDetail(dirName); }
function configureDomainApp() {
  // The apps list, with the filter box ready: pick the app this domain should serve.
  showTab('apps', {});
  setTimeout(function() {
    var f = document.getElementById('apps-filter');
    if (f) { f.value = ''; filterApps(''); f.focus(); f.scrollIntoView({block: 'center'}); }
  }, 150);
}
async function configureApp(dirName, appName) {
  var name = prompt('App name for configuration:', appName || dirName);
  if (!name) return;
  var r = await api('apps/configure', {app: dirName, name: name});
  if (r.error) alert(r.error);
  else if (r.output) alert(r.output);
  loadApps();
}
async function serveApp(name, enable) {
  if (enable) {
    var a = _appsData.find(function(x){return x.dirName===name});
    var domain = a && a.url ? a.url : location.hostname;
    if (!confirm('Enable "' + name + '"?\nIt will be served at: ' + domain)) return;
  }
  var r = await api('apps/serve', {app:name, enable:enable});
  if (r.error) return alert(r.error);
  loadApps();
}
function editAppsDir() {
  document.getElementById('apps-dir-input').value = document.getElementById('apps-dir-path').textContent;
  document.getElementById('apps-dir-edit').classList.remove('hidden');
  document.getElementById('apps-dir-path').style.display = 'none';
  document.getElementById('apps-dir-input').focus();
}
function cancelAppsDir() {
  document.getElementById('apps-dir-edit').classList.add('hidden');
  document.getElementById('apps-dir-path').style.display = '';
}
async function saveAppsDir() {
  var dir = document.getElementById('apps-dir-input').value.trim();
  var r = await api('apps/setdir', {dir: dir});
  if (r.error) return alert(r.error);
  cancelAppsDir();
  loadApps();
}
async function openFolder(dir, editor) {
  await api('apps/open', {dir:dir, editor:editor});
}

// Playground
async function runPlayground() {
  var code = document.getElementById('pg-code').value;
  var outEl = document.getElementById('pg-output');
  var timeEl = document.getElementById('pg-time');
  var btn = document.getElementById('pg-run');
  btn.disabled = true; btn.textContent = '⏳ Running...';
  outEl.textContent = '';
  outEl.style.color = 'var(--grn)';
  timeEl.textContent = '';
  try {
    var r = await api('playground/run', {code: code});
    outEl.innerHTML = ansiToHtml(r.output || '(no output)');
    if (r.error) { outEl.innerHTML += '\n\n⚠ ' + escHtml(r.error); outEl.style.color = 'var(--red)'; }
    if (r.ms) timeEl.textContent = r.ms + 'ms';
  } catch(e) {
    outEl.textContent = 'Error: ' + e.message;
    outEl.style.color = 'var(--red)';
  }
  btn.disabled = false; btn.textContent = '▶ Run';
}
function clearPlayground() {
  document.getElementById('pg-output').textContent = '';
  document.getElementById('pg-time').textContent = '';
}
// Ctrl+Enter to run
document.addEventListener('keydown', function(e) {
  if ((e.ctrlKey || e.metaKey) && e.key === 'Enter' && !document.getElementById('tab-playground').classList.contains('hidden')) {
    e.preventDefault(); runPlayground();
  }
});

// Scripts
async function loadAppSelect() {
  var d = await api('apps');
  var sel = document.getElementById('script-app');
  sel.innerHTML = (d.apps||[]).map(function(a) {
    return '<option value="'+escHtml(a.dirName)+'">'+escHtml(a.name)+'</option>';
  }).join('');
  loadScripts();
}
async function loadScripts() {
  var app = document.getElementById('script-app').value;
  if (!app) return;
  var d = await api('scripts', {app:app});
  var sel = document.getElementById('script-name');
  sel.innerHTML = (d.scripts||[]).map(function(s) {
    return '<option value="'+escHtml(s.name)+'">'+escHtml(s.name)+' ('+escHtml(s.scope)+')</option>';
  }).join('');
}
async function runScript() {
  var app = document.getElementById('script-app').value;
  var script = document.getElementById('script-name').value;
  var args = document.getElementById('script-args').value.split(/\s+/).filter(Boolean);
  var out = document.getElementById('script-output');
  out.classList.remove('hidden');
  out.textContent = 'Running '+script+'...';
  var r = await api('scripts/run', {app:app, script:script, args:args});
  out.innerHTML = ansiToHtml(r.output||'(no output)') + '\n\n' + escHtml('Exit code: '+(r.exitCode||'0'));
}
function quickScript(name, args) {
  var app = document.getElementById('script-app').value;
  if (!app) return alert('Select an app first');
  document.getElementById('script-name').value = name;
  document.getElementById('script-args').value = args||'';
  runScript();
}

// Plugins
function showAddPlugin() {
  document.getElementById('add-plugin-form').classList.remove('hidden');
  document.getElementById('plugin-name').focus();
}
function hideAddPlugin() {
  document.getElementById('add-plugin-form').classList.add('hidden');
  document.getElementById('plugin-log').style.display = 'none';
}
function hidePrivateDialog() {
  document.getElementById('plugin-private-dialog').classList.add('hidden');
}
async function addPlugin() {
  var name = document.getElementById('plugin-name').value.trim();
  if (!name) return alert('Enter a plugin name');
  var log = document.getElementById('plugin-log');
  log.style.display = 'block';
  log.style.color = 'var(--dim)';
  log.textContent = 'Cloning https://github.com/Qbix/' + name + '...\n';
  try {
    var r = await api('plugins/add', {name: name});
    if (r.private) {
      hideAddPlugin();
      var d = document.getElementById('plugin-private-dialog');
      document.getElementById('plugin-private-name').textContent = name;
      var subject = encodeURIComponent('Access to ' + name + ' plugin');
      var body = encodeURIComponent('Hi Qbix team,\n\nI would like access to the ' + name + ' plugin for my project.\n\nThanks!');
      document.getElementById('plugin-contact-link').href = 'mailto:team@qbix.com?subject=' + subject + '&body=' + body;
      d.classList.remove('hidden');
    } else if (r.error) {
      log.textContent += '\n⚠ ' + r.error;
      log.style.color = 'var(--red)';
    } else {
      log.textContent += (r.output || '') + '\n✅ Installed!';
      log.style.color = 'var(--grn)';
      setTimeout(function() { hideAddPlugin(); loadPlugins(); }, 1500);
    }
  } catch(e) {
    log.textContent += '\nError: ' + e.message;
    log.style.color = 'var(--red)';
  }
}

function getPluginsBranch() {
  var sel = document.getElementById('plugins-branch-select');
  return sel ? sel.value : '';
}

async function populatePluginsBranchSelect() {
  var sel = document.getElementById('plugins-branch-select');
  if (!sel) return;
  var cur = sel.value;
  try {
    var r = await api('branches');
    var branches = r.branches || [];
    sel.innerHTML = '<option value="">trunk (default)</option>';
    branches.forEach(function(b) {
      var key = b.appHost + '/' + b.name;
      sel.innerHTML += '<option value="' + escHtml(key) + '">' + escHtml(key) + '</option>';
    });
    if (cur) sel.value = cur;
  } catch(e) { /* keep just trunk */ }
}

async function populatePluginsAppSelect() {
  var sel = document.getElementById('plugins-app-select');
  if (!sel) return;
  var cur = sel.value;
  if (!_appsData || !_appsData.length) {
    try { var ar = await api('apps'); _appsData = ar.apps || []; } catch (e) { /* keep the default entry */ }
  }
  var apps = _appsData || [];
  sel.innerHTML = '<option value="">this domain\'s app</option>' + apps.map(function(a) {
    return '<option value="' + escAttr(a.dirName) + '">' + escHtml(a.name) + '</option>';
  }).join('');
  if (cur) sel.value = cur;
}
async function loadPlugins() {
  // Populate branch selector (non-blocking if already done)
  populatePluginsBranchSelect();

  var branch = getPluginsBranch();
  await populatePluginsAppSelect();
  var pAppSel = document.getElementById('plugins-app-select');
  var pBody = {};
  if (branch) pBody.branch = branch;
  if (pAppSel && pAppSel.value) pBody.app = pAppSel.value;
  var r = await api('qbix/plugins', pBody);
  var info = document.getElementById('qbix-plugins-info');
  var list = document.getElementById('qbix-plugins-list');

  var topHtml = '';
  if (r.app) {
    topHtml += '<div class="card" style="margin-bottom:12px"><strong>' + r.app + '</strong> v' + (r.appVersion||'?')
      + (r.branch ? ' <span style="font-size:11px;padding:1px 6px;border-radius:6px;background:var(--ac);color:#fff">branch: ' + escHtml(r.branch) + '</span>' : '')
      + (r.pluginsDir ? '<span style="color:var(--dim);font-size:11px;margin-left:8px">' + r.pluginsDir + '</span>' : '')
      + (r.dbError ? '<div style="color:var(--red);font-size:12px;margin-top:4px">DB: ' + escHtml(r.dbError) + '</div>' : '')
      + '</div>';
  } else {
    topHtml += '<div class="card" style="margin-bottom:12px;color:var(--dim)">No Qbix app detected. Point --app or --root at a Qbix app directory.</div>';
  }

  // Download from URL
  topHtml += '<div class="card" style="margin-bottom:12px">';
  topHtml += '<div style="font-size:12px;margin-bottom:6px;color:var(--dim)">Download plugin from GitHub or URL</div>';
  topHtml += '<div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap">';
  topHtml += '<input id="qbix-dl-url" type="text" placeholder="https://github.com/Qbix/PluginName" style="flex:1;min-width:200px;padding:5px 8px;font-size:12px;background:var(--card);border:1px solid var(--brd);color:var(--fg);border-radius:4px">';
  topHtml += '<input id="qbix-dl-name" type="text" placeholder="PluginName (optional)" style="width:140px;padding:5px 8px;font-size:12px;background:var(--card);border:1px solid var(--brd);color:var(--fg);border-radius:4px">';
  topHtml += '<button class="btn btn-primary" style="font-size:11px;padding:5px 12px" onclick="downloadPlugin()">Clone</button>';
  topHtml += '</div></div>';

  // Installer controls
  topHtml += '<div class="card" style="margin-bottom:12px">';
  topHtml += '<div style="font-size:12px;margin-bottom:6px;color:var(--dim)">Qbix Installer (scripts/Q/install.php)';
  if (branch) topHtml += ' <span style="font-size:10px;color:var(--ac)">[branch: ' + escHtml(branch) + ']</span>';
  topHtml += '</div>';
  topHtml += '<div style="display:flex;gap:6px;flex-wrap:wrap">';
  topHtml += '<button class="btn btn-primary" style="font-size:11px;padding:5px 12px" onclick="qbixInstall(\'all\')">Install All (--all)</button>';
  topHtml += '<button class="btn btn-ghost" style="font-size:11px;padding:5px 12px" onclick="qbixInstall(\'plugins\')">--plugins</button>';
  topHtml += '<button class="btn btn-ghost" style="font-size:11px;padding:5px 12px" onclick="qbixInstall(\'app\')">--app</button>';
  topHtml += '<button class="btn btn-ghost" style="font-size:11px;padding:5px 12px" onclick="qbixInstall(\'composer\')">--composer</button>';
  topHtml += '<button class="btn btn-ghost" style="font-size:11px;padding:5px 12px" onclick="qbixInstall(\'npm\')">--npm</button>';
  topHtml += '</div>';
  topHtml += '<pre id="qbix-install-output" style="display:none;margin-top:8px;font-size:11px;max-height:300px;overflow:auto;white-space:pre-wrap"></pre>';
  topHtml += '</div>';

  info.innerHTML = topHtml;
  
  if (!r.plugins || !r.plugins.length) {
    list.innerHTML = '<div class="card"><p style="color:var(--dim)">No plugins found.</p></div>';
    return;
  }
  
  list.innerHTML = r.plugins.map(function(p) {
    var statusBadge = {
      'installed': '<span style="color:var(--grn)">\u2713 installed</span>',
      'available': '<span style="color:var(--dim)">available</span>',
      'upgradable': '<span style="color:var(--yel)">\u2191 upgrade</span>',
      'missing': '<span style="color:var(--red)">\u2717 missing</span>'
    }[p.status] || p.status;
    
    var schemaBadge = '';
    if (p.schemaVersion) {
      schemaBadge = p.schemaStatus === 'current'
        ? ' <span style="color:var(--grn);font-size:11px">schema ' + p.schemaVersion + '</span>'
        : ' <span style="color:var(--yel);font-size:11px">schema ' + p.schemaVersion + ' \u2191</span>';
      if (p.db) schemaBadge += ' <span style="color:var(--dim);font-size:10px">(' + p.db + ')</span>';
    }
    
    var versions = '';
    if (p.availableVersion) versions += '<span style="font-size:11px;color:var(--dim)">v' + p.availableVersion + '</span> ';
    if (p.installedVersion && p.installedVersion !== p.availableVersion) versions += '<span style="font-size:11px;color:var(--dim)">installed: ' + p.installedVersion + '</span> ';
    
    // Package manager badges
    var pkgBadges = '';
    if (p.hasPackageJson) pkgBadges += ' <span style="font-size:9px;padding:1px 4px;border-radius:2px;background:#cb3837;color:#fff" title="Has package.json">npm</span>';
    if (p.hasComposerJson) pkgBadges += ' <span style="font-size:9px;padding:1px 4px;border-radius:2px;background:#885630;color:#fff" title="Has composer.json">composer</span>';
    if (p.hasNodeModules) pkgBadges += ' <span style="font-size:9px;color:var(--grn)" title="node_modules exists">\u2713npm</span>';
    if (p.hasVendor) pkgBadges += ' <span style="font-size:9px;color:var(--grn)" title="vendor exists">\u2713vendor</span>';
    
    // Dependency warning
    var depWarn = '';
    if (p.requires && Object.keys(p.requires).length) {
      var reqNames = Object.keys(p.requires);
      requires = ' <span style="font-size:10px;color:var(--dim)">needs ' + reqNames.join(', ') + '</span>';
      // Check if dependencies are installed
      var missingDeps = reqNames.filter(function(dep) {
        return !r.plugins.some(function(pp) { return pp.name === dep && (pp.status === 'installed' || pp.status === 'upgradable'); });
      });
      if (missingDeps.length && (p.status === 'available' || p.status === 'upgradable')) {
        depWarn = '<div style="font-size:11px;color:var(--yel);margin-top:4px;padding:4px 8px;background:rgba(234,179,8,.08);border-radius:4px">'
          + '⚠ Missing dependencies: <strong>' + missingDeps.join(', ') + '</strong> — install them first</div>';
      }
    } else {
      var requires = '';
    }

    var extra = '';
    if (p.extra && Object.keys(p.extra).length) {
      extra = '<details style="margin-top:4px"><summary style="font-size:11px;color:var(--dim);cursor:pointer">extra</summary><pre style="font-size:10px;margin-top:4px;max-height:80px;overflow:auto">' + escHtml(JSON.stringify(p.extra, null, 2)) + '</pre></details>';
    }

    // Action buttons
    var bs = 'font-size:10px;padding:2px 7px;margin-left:3px';
    var btns = '';
    if (p.hasDir) {
      btns += '<button class="btn btn-ghost" style="' + bs + '" onclick="viewPluginSchema(\'' + p.name + '\')">Scripts</button>';
      if (p.status === 'available' || p.status === 'upgradable') {
        btns += '<button class="btn btn-primary" style="' + bs + '" onclick="qbixInstall(\'plugin-full\',\'' + p.name + '\')">' + (p.status === 'upgradable' ? 'Upgrade' : 'Install') + '</button>';
      }
      if (p.hasPackageJson && !p.hasNodeModules) {
        btns += '<button class="btn btn-ghost" style="' + bs + '" onclick="qbixNpm(\'install\',\'' + p.name + '\')">npm install</button>';
      }
      if (p.hasPackageJson && p.hasNodeModules) {
        btns += '<button class="btn btn-ghost" style="' + bs + '" onclick="qbixNpm(\'update\',\'' + p.name + '\')">npm update</button>';
      }
    }

    return '<div class="card" style="margin-bottom:4px;padding:8px 12px">'
      + '<div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:4px">'
      + '<div><strong>' + p.name + '</strong>'
      + (p.declared ? ' <span style="font-size:9px;background:var(--dim);color:var(--bg);padding:1px 4px;border-radius:2px">declared</span>' : '')
      + ' ' + statusBadge + schemaBadge + pkgBadges + ' ' + versions + requires + '</div>'
      + '<div>' + btns + '</div>'
      + '</div>'
      + depWarn
      + extra
      + '<pre id="plugin-scripts-' + p.name + '" style="display:none;margin-top:4px;font-size:10px;max-height:120px;overflow:auto"></pre>'
      + '</div>';
  }).join('');

  // Bulk "Update All" button if any plugins are upgradable
  var upgradable = r.plugins.filter(function(p){ return p.status === 'upgradable'; });
  if (upgradable.length > 0) {
    list.innerHTML = '<div class="card" style="margin-bottom:8px;padding:8px 12px;display:flex;justify-content:space-between;align-items:center">'
      + '<span style="font-size:12px"><strong>' + upgradable.length + '</strong> plugin' + (upgradable.length > 1 ? 's' : '') + ' can be upgraded</span>'
      + '<button class="btn btn-primary" style="font-size:11px;padding:5px 12px" onclick="qbixInstall(\'plugins\')">↑ Update All Plugins</button>'
      + '</div>' + list.innerHTML;
  }
}

async function downloadPlugin() {
  var url = document.getElementById('qbix-dl-url').value.trim();
  var name = document.getElementById('qbix-dl-name').value.trim();
  if (!url) { alert('Enter a URL'); return; }
  var out = document.getElementById('qbix-install-output');
  out.style.display = 'block';
  out.textContent = 'Downloading ' + url + '...';
  var r = await api('frameworks/pkg-download', {framework: 'qbix', source: url, target: name});
  out.innerHTML = (r.cmd ? escHtml('$ ' + r.cmd) + '\n\n' : '') + ansiToHtml(r.output || r.error || 'Done');
  if (!r.error) setTimeout(function(){ loadPlugins(); }, 500);
}

async function qbixInstall(action, plugin) {
  var out = document.getElementById('qbix-install-output');
  out.style.display = 'block';
  var branch = getPluginsBranch();
  var label = action + (plugin ? ' ' + plugin : '') + (branch ? ' [' + branch + ']' : '');
  out.textContent = 'Running installer (' + label + ')...';
  var payload = {action: action, plugin: plugin || ''};
  if (branch) payload.branch = branch;
  var r = await api('qbix/installer', payload);
  out.innerHTML = (r.cmd ? escHtml('$ ' + r.cmd) + '\n\n' : '') + ansiToHtml(r.output || r.error || 'Done');
  if (!r.error) setTimeout(function(){ loadPlugins(); }, 500);
}

async function qbixNpm(action, target) {
  var out = document.getElementById('qbix-install-output');
  out.style.display = 'block';
  out.textContent = 'Running npm ' + action + ' for ' + target + '...';
  var r = await api('qbix/npm', {action: action, target: target});
  out.innerHTML = (r.cmd ? escHtml('$ ' + r.cmd) + '\n\n' : '') + ansiToHtml(r.output || r.error || 'Done');
  if (!r.error) setTimeout(function(){ loadPlugins(); }, 500);
}

async function installQbixPlugin(name) {
  qbixInstall('plugin-full', name);
}

async function viewPluginSchema(name) {
  var el = document.getElementById('plugin-scripts-' + name);
  if (el.style.display !== 'none') { el.style.display = 'none'; return; }
  el.style.display = 'block';
  el.textContent = 'Loading...';
  var r = await api('qbix/plugins/schema', {plugin: name});
  if (r.scripts && r.scripts.length) {
    el.textContent = 'Schema version: ' + (r.schemaVersion || 'none') + '\n\nInstall scripts:\n' + r.scripts.join('\n');
  } else {
    el.textContent = 'No install scripts found for ' + name;
  }
}

// System
// Servers
// ── Nearby / Transport ──────────────────────────────
async function loadNearby() {
  try {
    const d = await api('transport/status');
    // Identity
    const idEl = document.getElementById('nearby-identity');
    if (d.mesh_id) {
      idEl.innerHTML = '<strong>' + escHtml(d.mesh_name || 'This device') + '</strong><br>' + escHtml(d.mesh_id);
    } else {
      idEl.textContent = 'Not initialized';
    }
    // Transports
    const tEl = document.getElementById('nearby-transport-list');
    const transports = d.transports || {};
    let tHtml = '';
    for (const [name, enabled] of Object.entries(transports)) {
      const dot = enabled ? '🟢' : '⚪';
      tHtml += '<span style="margin-right:14px">' + dot + ' ' + name + '</span>';
    }
    tEl.innerHTML = tHtml || 'None configured';
    // Peers
    const pEl = document.getElementById('nearby-peers');
    const peers = d.peers || [];
    if (peers.length === 0) {
      pEl.innerHTML = '<div class="card"><p style="color:var(--dim)">No nearby peers detected.</p></div>';
    } else {
      let html = '';
      for (const p of peers) {
        const ago = Math.floor(Date.now()/1000) - (p.lastSeen || 0);
        const transport = p.transport || '?';
        const hops = p.hops > 0 ? ' (' + p.hops + ' hops)' : ' (direct)';
        const encrypted = p.sessionEstablished ? ' 🔒' : '';
        html += '<div class="card" style="margin-bottom:8px;display:flex;justify-content:space-between;align-items:center">'
          + '<div><strong>' + escHtml(p.name || (p.peer_id || '').substring(0,8)) + '</strong>' + encrypted
          + '<br><span style="font-size:11px;color:var(--dim)">' + escHtml(transport) + hops
          + ' · ' + (ago < 5 ? 'just now' : ago + 's ago')
          + '</span><br><span style="font-size:10px;font-family:monospace;color:var(--dim)">' + escHtml((p.peer_id || '').substring(0,16)) + '…</span></div>'
          + '<button class="btn btn-ghost" onclick="disconnectPeer(\'' + (p.peer_id || '').replace(/\\/g,'\\\\').replace(/'/g,"\\'") + '\')">Disconnect</button>'
          + '</div>';
      }
      pEl.innerHTML = html;
    }
    // Sessions
    const sEl = document.getElementById('nearby-session-list');
    const sessions = d.sessions || [];
    if (sessions.length === 0) {
      sEl.textContent = 'No encrypted sessions active';
    } else {
      sEl.innerHTML = sessions.map(s => '<code style="font-size:11px">' + (s || '').substring(0,16) + '…</code>').join(', ');
    }
    // Routing table
    const rEl = document.getElementById('nearby-route-list');
    const routes = d.routes || [];
    if (routes.length === 0) {
      rEl.textContent = 'No routes';
    } else {
      let rHtml = '<table style="width:100%;font-size:12px;border-collapse:collapse">'
        + '<tr style="color:var(--dim)"><td>Destination</td><td>Via</td><td>Hops</td><td>Name</td></tr>';
      for (const r of routes) {
        const dest = (r.destination || '').substring(0,12) + '…';
        const hop = r.next_hop === r.destination ? 'direct' : (r.next_hop || '').substring(0,12) + '…';
        rHtml += '<tr><td><code>' + escHtml(dest) + '</code></td><td>' + escHtml(hop) + '</td><td>' + (r.hops ?? '?') + '</td><td>' + escHtml(r.name || '') + '</td></tr>';
      }
      rHtml += '</table>';
      rEl.innerHTML = rHtml;
    }
  } catch (e) {
    document.getElementById('nearby-peers').innerHTML = '<div class="card"><p style="color:var(--warn)">Error loading: ' + escHtml(e.message) + '</p></div>';
  }
}
async function connectToPeer() {
  const addr = document.getElementById('nearby-connect-addr').value.trim();
  if (!addr) return;
  const el = document.getElementById('nearby-connect-result');
  el.textContent = 'Connecting…';
  try {
    const d = await api('transport/connect', {address: addr});
    if (d.connected) {
      el.innerHTML = '✓ Connected to <strong>' + escHtml(d.name || (d.peer_id||'').substring(0,12)) + '</strong>' + (d.encrypted ? ' 🔒' : '');
      loadNearby();
    } else {
      el.textContent = '✗ ' + (d.error || 'Connection failed');
    }
  } catch (e) { el.textContent = '✗ ' + e.message; }
}
async function disconnectPeer(peerId) {
  if (!confirm('Disconnect peer ' + peerId.substring(0,8) + '?')) return;
  await api('transport/unregister', {peer_id: peerId});
  loadNearby();
}

function showAddServer() { document.getElementById('add-server-form').classList.remove('hidden'); document.getElementById('srv-name').focus(); }
function hideAddServer() { document.getElementById('add-server-form').classList.add('hidden'); }
async function saveServer() {
  var s = { name: document.getElementById('srv-name').value.trim(), host: document.getElementById('srv-host').value.trim(),
    user: document.getElementById('srv-user').value.trim(), path: document.getElementById('srv-path').value.trim(),
    key: document.getElementById('srv-key').value.trim() };
  if (!s.name || !s.host) return alert('Name and host required');
  var r = await api('servers/add', s);
  if (r.error) return alert(r.error);
  hideAddServer(); loadServers();
}
async function deployTo(name, ev) {
  var btn = ev && ev.target ? ev.target : null;
  if (btn) { btn.disabled = true; btn.textContent = '⏳ Deploying...'; }
  var r = await api('servers/deploy', {target: name});
  if (btn) { btn.disabled = false; btn.textContent = '⬆ Deploy'; }
  if (r.error) alert(r.error);
  else alert('✨ Deployed ' + (r.files||0) + ' files to ' + name);
}
async function removeServer(name) {
  if (!confirm('Remove server "' + name + '"?')) return;
  await api('servers/remove', {name: name});
  loadServers();
}
async function loadServers() {
  var d = await api('servers');
  var el = document.getElementById('servers-list');
  if (!d.servers || !d.servers.length) {
    el.innerHTML = '<div class="card"><p style="color:var(--dim)">No remote servers configured. Add one to deploy your app.</p></div>';
    return;
  }
  el.innerHTML = d.servers.map(function(s) { var sn = s.name.replace(/\\/g,'\\\\').replace(/'/g,"\\'"); return ''
    + '<div class="app-row">'
    + '<span class="dot on"></span>'
    + '<span class="app-name">' + escHtml(s.name) + '</span>'
    + '<span class="app-url">' + escHtml(s.user + '@' + s.host + ':' + s.path) + '</span>'
    + '<div class="btn-row">'
    + '<button class="btn btn-sm btn-primary" onclick="deployTo(\'' + sn + '\',event)">⬆ Deploy</button>'
    + '<button class="btn btn-sm btn-red" onclick="removeServer(\'' + sn + '\')">✕</button>'
    + '</div></div>';
  }).join('');
}

async function loadSystem() {
  var d = await detectTools();
  var el = document.getElementById('system-info');
  
  // Key extensions to highlight
  var keyExts = ['pdo_sqlite','pdo_mysql','pdo_pgsql','openssl','curl','mbstring','gd','zip','sockets','pcntl','posix','readline'];
  var extStatus = keyExts.map(function(e) {
    var has = d.extensions && d.extensions.indexOf(e) !== -1;
    return (has ? '<span style="color:var(--grn)">✅</span>' : '<span style="color:var(--red)">❌</span>') + ' ' + e;
  }).join('&nbsp;&nbsp;');
  var extCount = d.extensions ? d.extensions.length : 0;
  
  var items = [
    ['PHP', d.php + ' <span style="font-size:11px;color:var(--dim)">' + extCount + ' extensions</span>'],
    ['OS', d.os + ' ' + d.arch],
    ['Memory Limit', d.memoryLimit],
    ['pcntl', d.hasPcntl ? '✅' : '❌'],
    ['APCu', d.hasApcu ? '✅' : '❌'],
    ['Composer', d.hasComposer ? '✅ installed' : '❌ not found'],
    ['Node.js', d.hasNode ? '✅ installed' : '<span style="color:var(--red)">❌ not found</span>'],
    ['npm', d.hasNpm ? '✅ installed' : '❌ requires Node.js'],
    ['Git', d.hasGit ? '✅ installed' : '❌ not found'],
  ];
  if (d.platform) items.push(['Platform', d.platform]);
  if (d.appDir) items.push(['App Dir', d.appDir]);
  if (d.diskFree) items.push(['Disk Free', d.diskFree]);
  if (d.serverVersion) items.push(['Server', d.serverVersion]);
  
  el.innerHTML = items.map(function(i) {
    return '<div class="card"><div class="stat-lbl">'+i[0]+'</div><div class="stat-val" style="font-size:16px">'+i[1]+'</div></div>';
  }).join('');
  
  // Extensions detail
  el.innerHTML += '<div class="card" style="grid-column:1/-1"><div class="stat-lbl">Key Extensions</div><div style="font-size:12px;line-height:2;margin-top:4px">' + extStatus + '</div>'
    + '<details style="margin-top:8px"><summary style="font-size:11px;color:var(--dim);cursor:pointer">All ' + extCount + ' extensions</summary>'
    + '<div style="font-size:11px;color:var(--dim);margin-top:4px;column-count:3;column-gap:12px">' + (d.extensions||[]).sort().join('<br>') + '</div></details></div>';

  // Platform install section
  var pEl = document.getElementById('platform-status');
  if (d.platform) {
    pEl.innerHTML = '<p style="color:var(--grn)">✅ Platform installed at <code style="font-size:12px">'+d.platform+'</code></p>';
  } else {
    pEl.innerHTML = ''
      + '<p style="color:var(--dim);margin-bottom:12px">Qbix Platform adds user accounts, real-time streams, assets, and 20+ plugins to your app.</p>'
      + '<div class="form-row"><label>Install to</label>'
      + '<input id="platform-dir" value="'+(d.appDir ? d.appDir.replace(/[/\\][^/\\]*$/,'') : '')+'/platform" '
      + 'style="font-size:12px" placeholder="/path/to/install/platform"></div>'
      + '<div class="btn-row">'
      + '<button class="btn btn-primary" onclick="installPlatform()" id="platform-btn">Clone from GitHub</button>'
      + '</div>'
      + '<pre id="platform-log" style="display:none;margin-top:12px;font-size:11px;color:var(--dim);max-height:200px;overflow:auto;background:rgba(0,0,0,.2);padding:8px;border-radius:4px"></pre>';
  }
}

async function installPlatform() {
  var dir = document.getElementById('platform-dir').value.trim();
  if (!dir) return alert('Enter a directory path');
  var btn = document.getElementById('platform-btn');
  var log = document.getElementById('platform-log');
  btn.disabled = true; btn.textContent = '⏳ Cloning...';
  log.style.display = 'block'; log.textContent = 'git clone https://github.com/Qbix/Platform.git ' + dir + '\n';
  try {
    var r = await api('platform/install', {dir: dir});
    if (r.error) { log.textContent += '\n⚠ ' + r.error; log.style.color = 'var(--red)'; }
    else { log.textContent += r.output + '\n✅ Done! Refresh to see plugins.'; log.style.color = 'var(--grn)'; }
  } catch(e) { log.textContent += '\nError: ' + e.message; log.style.color = 'var(--red)'; }
  btn.disabled = false; btn.textContent = 'Clone from GitHub';
}

async function clearServerCache() {
  var el = document.getElementById('cache-clear-result');
  el.style.display = 'block';
  el.textContent = 'Clearing...';
  try {
    var r = await api('cache/clear');
    if (r.error) { el.textContent = '⚠ ' + r.error; el.style.color = 'var(--red)'; }
    else {
      var items = r.cleared && r.cleared.length ? r.cleared.join(', ') : 'nothing to clear';
      el.textContent = '✅ Cleared: ' + items;
      el.style.color = 'var(--grn)';
    }
  } catch(e) { el.textContent = 'Error: ' + e.message; el.style.color = 'var(--red)'; }
  setTimeout(function() { el.style.display = 'none'; el.style.color = ''; }, 5000);
}

async function runHealthCheck() {
  var btn = document.getElementById('health-check-btn');
  var el = document.getElementById('health-check-results');
  btn.disabled = true; btn.textContent = '⏳ Checking...';
  el.style.display = 'block';
  el.innerHTML = '<div class="card" style="color:var(--dim)">Running health checks...</div>';
  try {
    var r = await api('system/health');
    var statusIcon = {ok: '✅', warning: '⚠️', critical: '❌'};
    var statusColor = {ok: 'var(--grn)', warning: 'var(--yel)', critical: 'var(--red)'};
    var html = '<div class="card" style="margin-bottom:8px;padding:10px 14px">';
    html += '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px">';
    html += '<strong style="font-size:14px">Health Check</strong>';
    html += '<span style="font-size:13px;color:' + (statusColor[r.overall] || 'var(--dim)') + '">' + (statusIcon[r.overall] || '') + ' ' + (r.overall || 'unknown').toUpperCase() + '</span>';
    html += '</div>';
    (r.checks || []).forEach(function(c) {
      var icon = statusIcon[c.status] || '❓';
      var color = statusColor[c.status] || 'var(--dim)';
      html += '<div style="display:flex;align-items:center;gap:8px;padding:4px 0;border-top:1px solid var(--brd)">';
      html += '<span style="font-size:13px">' + icon + '</span>';
      html += '<span style="font-size:12px;min-width:180px"><strong>' + escHtml(c.name) + '</strong></span>';
      html += '<span style="font-size:12px;color:' + color + '">' + escHtml(c.detail) + '</span>';
      html += '</div>';
    });
    html += '</div>';
    el.innerHTML = html;
  } catch(e) {
    el.innerHTML = '<div class="card" style="color:var(--red)">Error: ' + escHtml(e.message) + '</div>';
  }
  btn.disabled = false; btn.textContent = '🩺 Health Check';
}

// ── Domains ─────────────────────────────────────────
async function loadDomains() {
  var r = await api('domains');
  _domainsData = r.domains || [];
  try { var ar = await api('apps'); if (ar && ar.apps) _appsData = ar.apps; } catch (e) { /* pickers fall back to what is loaded */ }
  var here = currentDomainEntry();
  if (here) _domainsData.sort(function(x, y) { return (y === here ? 1 : 0) - (x === here ? 1 : 0); });
  var el = document.getElementById('domains-list');
  // Clear any filter
  var filterInput = document.getElementById('domains-filter');
  if (filterInput) filterInput.value = '';
  if (!_domainsData.length) {
    el.innerHTML = '<div class="card"><p style="color:var(--dim)">No domains configured. Add one below, or edit ' + cfgLink('Q.webserver.domains') + ' in the Config tab.</p></div>';
  } else {
    el.innerHTML = _domainsData.map(function(d) {
      var badge = d.certStatus === 'valid' ? '<span style="color:var(--grn)">\u2713 valid</span>'
        : d.certStatus === 'expiring' ? '<span style="color:var(--yel)">\u26a0 ' + d.certDaysLeft + ' days</span>'
        : d.certStatus === 'expired' ? '<span style="color:var(--red)">\u2717 expired</span>'
        : '<span style="color:var(--dim)">no cert</span>';
      var dn = d.domain.replace(/\\/g,'\\\\').replace(/'/g,"\\'");
      var certBtn = d.certStatus !== 'valid'
        ? '<button class="btn btn-primary" style="font-size:11px;padding:4px 10px" onclick="event.stopPropagation();provisionCert(\'' + dn + '\')" title="Request a free Let\'s Encrypt certificate">Provision</button>'
        : '<button class="btn btn-ghost" style="font-size:11px;padding:4px 10px" onclick="event.stopPropagation();provisionCert(\'' + dn + '\')" title="Renew the Let\'s Encrypt certificate">Renew</button>';
      if (d.certError && d.certStatus !== 'valid') {
        var ck = 'dom:' + d.domain;
        _certErr[ck] = {name: d.domain, error: d.certError, at: d.certErrorAt, via: d.certErrorVia, retry: function() { provisionCert(d.domain); }};
        badge = '<a href="#" style="color:var(--red)" title="The last certificate request failed" onclick="event.stopPropagation();showCertErrorKey(\'dom:' + dn + '\');return false">✗ Failed [ See Error ]</a>';
      }
      if (d.cdn && !d.certError && d.certStatus !== 'valid') {
        badge = '<span style="color:var(--dim)" title="Requests arrive through ' + escAttr(d.cdn) + ', which ends HTTPS itself, so no certificate is requested here automatically">Behind ' + escHtml(d.cdn) + '</span>';
      }
      if (d.proxied && !d.certError) {
        // nginx/Apache in front of this server holds the certificate
        certBtn = '';
        badge = '<span style="color:var(--dim)" title="The web server in front of this one handles TLS">TLS by proxy</span>';
      }
      var removeBtn = d.removable
        ? '<button class="btn btn-ghost" style="font-size:11px;padding:4px 10px;color:var(--red)" onclick="event.stopPropagation();removeDomain(\'' + dn + '\')" title="Stop serving this domain from the panel. The domain, its DNS, any certificate and the app\'s files are not touched.">Remove</button>'
        : '';
      // Find associated app
      var app = findAppForDomain(d);
      var appLink = domainAppPicker(d)
        + (d.suggested && !d.appDir
          ? ' <button class="btn btn-ghost btn-sm" style="font-size:11px;padding:3px 10px" onclick="event.stopPropagation();adoptDomain(' + _domainsData.indexOf(d) + ')" title="' + escAttr('Use ' + (d.suggested.file || 'the web server config') + (d.suggested.root ? ': root ' + d.suggested.root : '')) + '">Use ' + escHtml(d.suggested.appName || 'detected') + ' settings</button>'
          : '');
      var onclick = app
        ? ' onclick="showAppDetail(\'' + escAttr(app.dirName || app.name) + '\')"'
        : '';
      var meta = [];
      if (d.root) meta.push('Root: ' + escHtml(d.root));
      if (d.certExpires) meta.push('Expires: ' + escHtml(d.certExpires));
      // Per-domain auto-cache config
      var cacheConf = d.cache && d.cache.auto ? d.cache.auto : null;
      var cacheEnabled = cacheConf && cacheConf.enabled;
      var cacheFramework = cacheConf ? (cacheConf.framework || '') : '';
      var cacheBadge = cacheEnabled
        ? '<span style="color:var(--grn);font-size:11px" title="Auto-cache active">\u26a1 cached' + (cacheFramework ? ' (' + escHtml(cacheFramework) + ')' : '') + '</span>'
        : '';
      var dn2 = d.domain.replace(/\\/g,'\\\\').replace(/"/g,'\\"');
      var cacheToggle = '<div style="margin-top:8px;padding-top:8px;border-top:1px solid var(--brd);display:flex;align-items:center;gap:8px;flex-wrap:wrap" onclick="event.stopPropagation()">'
        + '<span style="font-size:11px;color:var(--dim)">Auto-cache:</span>'
        + '<label style="display:flex;align-items:center;gap:4px;cursor:pointer;font-size:11px">'
        + '<input type="checkbox" class="toggle" ' + (cacheEnabled ? 'checked' : '') + ' onchange="updateDomainCache(\'' + dn2 + '\', \'enabled\', this.checked)">'
        + '<span>' + (cacheEnabled ? 'On' : 'Off') + '</span></label>'
        + '<select onchange="updateDomainCache(\'' + dn2 + '\', \'framework\', this.value)" style="font-size:11px;padding:2px 6px;border-radius:4px;border:1px solid var(--brd);background:var(--card);color:var(--fg)">'
        + '<option value=""' + (!cacheFramework ? ' selected' : '') + '>No preset</option>'
        + '<option value="wordpress"' + (cacheFramework === 'wordpress' ? ' selected' : '') + '>WordPress</option>'
        + '<option value="drupal"' + (cacheFramework === 'drupal' ? ' selected' : '') + '>Drupal</option>'
        + '<option value="laravel"' + (cacheFramework === 'laravel' ? ' selected' : '') + '>Laravel</option>'
        + '<option value="symfony"' + (cacheFramework === 'symfony' ? ' selected' : '') + '>Symfony</option>'
        + '<option value="joomla"' + (cacheFramework === 'joomla' ? ' selected' : '') + '>Joomla</option>'
        + '<option value="qbix"' + (cacheFramework === 'qbix' ? ' selected' : '') + '>Qbix</option>'
        + '<option value="static"' + (cacheFramework === 'static' ? ' selected' : '') + '>Static site</option>'
        + '</select>'
        + '</div>';
      return '<div class="domain-card"' + onclick + (d === here ? ' style="outline:2px solid var(--ac);outline-offset:-2px"' : '') + '>'
        + '<div class="domain-top">'
        + '<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;min-width:0">'
        + '<span class="domain-name">' + escHtml(d.domain) + '</span>'
        + (d === here ? '<span style="font-size:11px;color:var(--ac)">\u2190 you are here</span>' : '')
        + appLink + ' ' + cacheBadge
        + '</div>'
        + '<div class="domain-actions">' + badge + ' ' + certBtn + ' ' + removeBtn + '</div>'
        + '</div>'
        + (meta.length ? '<div class="domain-meta">' + meta.join(' \u00b7 ') + '</div>' : '')
        + cacheToggle
        + '</div>';
    }).join('');
    // Auto-scroll to the current domain and highlight it
    setTimeout(function() {
      var cards = el.querySelectorAll('.domain-card');
      for (var i = 0; i < cards.length; i++) {
        var nameEl = cards[i].querySelector('.domain-name');
        if (nameEl && nameEl.textContent === location.hostname) {
          cards[i].style.borderColor = 'var(--accent)';
          cards[i].style.boxShadow = '0 0 0 1px var(--accent)';
          cards[i].scrollIntoView({behavior:'smooth', block:'center'});
          break;
        }
      }
    }, 100);
  }
  loadHosts();
}
async function loadHosts() {
  var r = await api('domains/hosts');
  var el = document.getElementById('hosts-info');
  if (!el) return;
  if (r.error) { el.innerHTML = '<div class="card"><p style="color:var(--dim)">' + r.error + '</p></div>'; return; }
  var html = '<h3 style="font-size:14px;margin:16px 0 8px">System Hosts <span style="font-size:11px;color:var(--dim)">(' + r.path + ')</span></h3>';
  if (r.domains && r.domains.length) {
    html += r.domains.map(function(d) {
      if (d.inHosts) {
        return '<div class="card" style="margin-bottom:6px;padding:8px 12px"><span style="color:var(--grn)">\u2713</span> <strong>' + d.domain + '</strong> \u2192 ' + d.hostsIp + '</div>';
      }
      var isLocalhost = d.domain.endsWith('.localhost');
      if (isLocalhost) {
        return '<div class="card" style="margin-bottom:6px;padding:8px 12px"><span style="color:var(--grn)">\u2713</span> <strong>' + d.domain + '</strong> <span style="color:var(--dim)">(resolves via .localhost)</span></div>';
      }
      return '<div class="card" style="margin-bottom:6px;padding:8px 12px"><span style="color:var(--yel)">\u26a0</span> <strong>' + d.domain + '</strong> <span style="color:var(--dim)">not in hosts</span>'
        + ' <button class="btn btn-primary" style="font-size:11px;padding:3px 8px;margin-left:8px" onclick="addHostsEntry(\'' + d.domain + '\')">Add to hosts</button></div>';
    }).join('');
  } else {
    html += '<div class="card"><p style="color:var(--dim)">No domains configured.</p></div>';
  }
  el.innerHTML = html;
}
async function addHostsEntry(hostname, ip) {
  ip = ip || '127.0.0.1';
  var r = await api('domains/hosts/add', {hostname: hostname, ip: ip});
  if (r.already) { alert(hostname + ' is already in your hosts file.'); return; }
  if (r.conflict) { alert(hostname + ' is mapped to ' + r.existingIp + ' (not ' + r.requestedIp + '). Edit your hosts file manually to change it.'); return; }
  if (r.added) { alert('Added ' + hostname + ' \u2192 ' + ip); loadHosts(); return; }
  if (r.needsElevation) {
    var cmd = r.commands.gui || r.commands.command;
    if (confirm(hostname + ' needs admin access to add to ' + r.entry + '.\n\nRun this command in your terminal:\n\n' + r.commands.command + '\n\nCopy to clipboard?')) {
      try { navigator.clipboard.writeText(r.commands.command); } catch(e) {}
    }
  }
}

async function updateDomainCache(domain, field, value) {
  var payload = { domain: domain };
  payload[field] = value;
  // When enabling with no framework set, just enable
  // When setting framework, also enable
  if (field === 'framework' && value) {
    payload.enabled = true;
  }
  try {
    var r = await api('domains/cache', payload);
    if (r.error) { alert(r.error); return; }
    loadDomains();
  } catch(e) {
    alert(e.message || 'Failed to update domain cache config');
  }
}
async function addDomain() {
  var name = document.getElementById('dom-name').value.trim();
  if (!name) return alert('Enter a domain');
  await api('domains/add', {domain:name, root:document.getElementById('dom-root').value.trim()||null, app:document.getElementById('dom-app').value.trim()||null, tls:document.getElementById('dom-tls').value});
  document.getElementById('dom-name').value=''; loadDomains();
}
async function removeDomain(n) { if(!confirm('Stop serving '+n+' from this panel?\n\nIts entry is deleted from the panel settings. No certificate, DNS record or app files are deleted.'))return; await api('domains/remove',{domain:n}); loadDomains(); }
async function provisionCert(n, email, force) {
  var b = {domain:n};
  if (email) b.email = email;
  if (force) b.force = true;
  var r = await api('domains/provision', b);
  if (r.proxied && !force) {
    if (!confirm(r.error + '\n\nRequest a certificate here anyway? ' + (r.cdn && r.cdn !== 'a reverse proxy'
      ? 'It only works if the CDN passes /.well-known/acme-challenge/ on port 80 through to this server (or the CDN is switched to DNS-only).'
      : 'It only works if /.well-known/acme-challenge/ on port 80 reaches this server. If nginx owns port 80 and does not forward it, the request will fail, and nginx would still need the certificate installed.'))) return;
    return provisionCert(n, email, true);
  }
  if (r.needsEmail) {
    // Let's Encrypt wants an address for expiry notices. Ask once; the server keeps it.
    var e = prompt((email ? r.error + '\n\n' : '') + "Email address for Let's Encrypt expiry notices:", email || '');
    if (!e) return;
    return provisionCert(n, e.trim(), force);
  }
  if (r.success && r.queued) return waitForCert(n);
  if (r.success) showToast('Done!');
  else showCertError(n, r.error || 'Failed', null, null, function() { provisionCert(n); });
  loadDomains();
}
// The server asks Let's Encrypt in a background process; look in every few seconds for how it went.
async function waitForCert(n) {
  showToast('Requesting a certificate for ' + n + '\u2026');
  for (var i = 0; i < 60; i++) {
    await new Promise(function(res) { setTimeout(res, 3000); });
    var s = await api('domains/provision-status', {domain: n});
    if (s.pending) continue;
    if (s.unknown) break;
    if (s.success) showToast('Certificate ready for ' + n, 5000);
    else showCertError(n, s.error || 'unknown error', s.at, s.via, function() { provisionCert(n); });
    loadDomains();
    return;
  }
  alert('Still working on ' + n + '. Look at the server log for how it ends.');
  loadDomains();
}
async function adoptDomain(i) {
  var d = _domainsData[i];
  if (!d || !d.suggested) return;
  var r = await api('domains/import', {domains: [d.suggested]});
  if (r.error) { alert(r.error); return; }
  loadDomains();
}

var _scannedDomains = [];
async function scanWebserverConfigs() {
  var btn = document.getElementById('scan-btn');
  btn.textContent = 'Scanning…'; btn.disabled = true;
  try {
    var r = await api('domains/scan');
    if (r.error) { alert(r.error); return; }
    _scannedDomains = r.domains || [];
    var panel = document.getElementById('scan-results');
    var scannedEl = document.getElementById('scan-scanned');
    var listEl = document.getElementById('scan-list');
    scannedEl.textContent = 'Scanned: ' + (r.scanned||[]).join(', ');
    if (!_scannedDomains.length) {
      listEl.innerHTML = '<p style="color:var(--dim);font-size:13px">No domains found in nginx, Apache, or Caddy configs.</p>';
    } else {
      listEl.innerHTML = _scannedDomains.map(function(d, i) {
        var src = '<span style="font-size:10px;padding:1px 6px;border-radius:6px;background:var(--bdr);color:var(--dim)">' + escHtml(d.source) + '</span>';
        return '<label style="display:flex;align-items:flex-start;gap:8px;padding:8px 0;border-bottom:1px solid var(--bdr);cursor:pointer">'
          + '<input type="checkbox" checked data-idx="'+i+'" style="margin-top:3px">'
          + '<div><strong>' + escHtml(d.domain) + '</strong> ' + src
          + (d.root ? '<div style="font-size:11px;color:var(--dim)">Root: ' + escHtml(d.root) + '</div>' : '')
          + (d.tls ? '<div style="font-size:11px;color:var(--dim)">TLS: ' + escHtml(d.tls) + '</div>' : '')
          + '<div style="font-size:11px;color:var(--dim)">From: ' + escHtml(d.file) + '</div>'
          + '</div></label>';
      }).join('');
    }
    panel.classList.remove('hidden');
  } catch(e) { alert('Scan failed: ' + e.message); }
  btn.textContent = '🔍 Scan nginx / Apache / Caddy'; btn.disabled = false;
}
async function importSelected() {
  var checks = document.querySelectorAll('#scan-list input[type=checkbox]:checked');
  var toImport = [];
  checks.forEach(function(c) {
    var idx = parseInt(c.getAttribute('data-idx'));
    if (_scannedDomains[idx]) toImport.push(_scannedDomains[idx]);
  });
  if (!toImport.length) { alert('No domains selected'); return; }
  var r = await api('domains/import', {domains: toImport});
  if (r.error) { alert(r.error); return; }
  alert('Imported ' + r.imported + ' domain(s)' + (r.skipped ? ', skipped ' + r.skipped + ' (already exist or invalid)' : ''));
  document.getElementById('scan-results').classList.add('hidden');
  loadDomains();
}
function toggleScanSelectAll(checked) {
  document.querySelectorAll('#scan-list input[type=checkbox]').forEach(function(c) { c.checked = checked; });
}

// ── Security & Attestation ──────────────────────────
async function loadSecurity() {
  var el = document.getElementById('sec-attestation');
  try {
    var r = await api('attestation');
    var html = '<div class="card"><h3 style="font-size:14px;margin-bottom:8px">Binary Attestation</h3>';
    html += '<div style="font-size:12px;margin-bottom:8px"><strong>Hash:</strong> <code style="font-size:11px">' + (r.binary_hash||'unknown') + '</code></div>';
    html += '<div style="font-size:12px;margin-bottom:8px"><strong>Size:</strong> ' + ((r.binary_size||0)/1024).toFixed(0) + ' KB</div>';
    var hasSigs = !!(r.signatures && r.signatures.length);
    if (hasSigs && r.verification) {
      var v = r.verification;
      var color = v.valid ? 'var(--grn)' : 'var(--red)';
      html += '<div style="font-size:12px;margin-bottom:8px"><strong>' + t('Status:') + '</strong> <span style="color:'+color+'">' + escHtml(v.label || '') + ' \u2014 ' + (v.valid ? t('VALID') : t('FAILED')) + '</span></div>';
      if (v.hash_matches === false) {
        html += '<div style="font-size:12px;color:var(--red)">\u26a0 ' + t('Binary was modified since signing') + '</div>';
      }
    }
    if (hasSigs) {
      html += '<h4 style="font-size:13px;margin:12px 0 6px">' + t('Signatures') + '</h4>';
      r.signatures.forEach(function(s) {
        html += '<div style="font-size:12px;padding:4px 0;border-top:1px solid var(--border)">';
        html += '<strong>' + escHtml(s.signer || '') + '</strong> <span style="color:var(--dim)">(key:' + escHtml((s.key_id||'?').slice(0,8)) + ')</span>';
        if (s.signed_at) html += ' <span style="color:var(--dim)">' + s.signed_at.slice(0,10) + '</span>';
        html += '</div>';
      });
    } else {
      html += '<div style="font-size:12px;color:var(--dim);line-height:1.5">' + t('This build has not been signed, so there is nothing to verify yet. Signing records a signature with your private key; anyone holding your public key can then confirm this binary is unchanged. Paste a private key in the form below, or use the CLI.') + '</div>';
    }
    if (r.rekor && r.rekor.uuid) {
      html += '<div style="font-size:12px;margin-top:10px;padding-top:8px;border-top:1px solid var(--border)"><strong>Transparency log:</strong> <a href="' + (r.rekor.url||'#') + '" target="_blank" style="color:#4a9eff">' + r.rekor.uuid.slice(0,24) + '...</a> <span style="color:var(--grn)">✓ on Rekor</span></div>';
    } else if (r.signed) {
      html += '<div style="font-size:12px;margin-top:10px;padding-top:8px;border-top:1px solid var(--border)"><strong>Transparency log:</strong> <span style="color:var(--dim)">not published</span> <button class="btn btn-ghost" style="font-size:10px;padding:2px 8px;margin-left:6px" onclick="publishRekor()">Publish to Sigstore Rekor</button></div>';
    }
    html += '</div>';
    el.innerHTML = html;
  } catch(e) {
    el.innerHTML = '<div class="card"><p style="color:var(--dim)">Attestation data unavailable.</p></div>';
  }
  // Trust status
  var trustEl = document.getElementById('sec-trust');
  try {
    var t = await api('trust');
    if (t.enabled) {
      var thtml = '<div class="card"><h3 style="font-size:14px;margin-bottom:8px">Code Trust (File Manifests)</h3>';
      thtml += '<div style="font-size:12px">Trusted keys: ' + (t.keys||[]).length + '</div>';
      if (t.verified && t.verified.length) {
        thtml += '<div style="font-size:12px;margin-top:6px">';
        t.verified.forEach(function(v) {
          var icon = v.ok ? '<span style="color:var(--grn)">✓</span>' : '<span style="color:var(--red)">✗</span>';
          thtml += '<div>' + icon + ' ' + v.dir + (v.errors && v.errors.length ? ' (' + v.errors.length + ' errors)' : '') + '</div>';
        });
        thtml += '</div>';
      }
      thtml += '</div>';
      trustEl.innerHTML = thtml;
    } else {
      trustEl.innerHTML = '<div class="card"><p style="font-size:12px;color:var(--dim)">' + t('Code trust is off.') + ' ' + cfgLink('Q.trust.enabled', t('Turn on {key}', {key: 'Q.trust.enabled'})) + ' ' + t('and add trusted keys.') + '</p></div>';
    }
  } catch(e) {}
}
async function signBinary() {
  var key = document.getElementById('sec-key').value.trim();
  var signer = document.getElementById('sec-signer').value.trim() || 'panel-user';
  if (!key) return alert('Paste a PEM private key');
  var r = await api('attestation/sign', {key: key, signer: signer});
  if (r.error) { alert(r.error); return; }
  alert('Signed! ' + r.signers + ' total signature(s)');
  document.getElementById('sec-key').value = '';
  loadSecurity();
}
async function verifyBinary() {
  var m = parseInt(document.getElementById('sec-m').value) || 1;
  var r = await api('attestation/verify?m=' + m);
  var el = document.getElementById('sec-verify-result');
  var color = r.valid ? 'var(--grn)' : 'var(--red)';
  var html = '<div style="color:'+color+';font-weight:700">' + (r.valid ? '✓ VALID' : '✗ FAILED') + ' — ' + escHtml(r.label || '') + '</div>';
  if (r.details) {
    r.details.forEach(function(d) {
      var icon = d.status === 'valid' ? '✓' : '✗';
      html += '<div style="font-size:12px">' + icon + ' ' + escHtml(d.signer) + ' (' + escHtml(d.status) + ')</div>';
    });
  }
  el.innerHTML = html;
}
async function publishRekor() {
  if (!confirm('Publish this binary\'s attestation to the public Sigstore Rekor transparency log?\n\nThis is permanent and publicly visible.')) return;
  var r = await api('attestation/publish-rekor', {});
  if (r.published) {
    alert('Published to Rekor!\n\nUUID: ' + r.uuid + '\n\nVerify at: ' + r.url);
    loadSecurity();
  } else {
    alert(r.error || 'Failed to publish');
  }
}

// ── API Keys ────────────────────────────────────────
function fillApiKeyRoles() {
  var sel = document.getElementById('ak-role');
  if (!sel) return;
  var names = {owner:'Owner', admin:'Admin', manager:'Manager', user:'User', analytics:'Analytics (read-only metrics)'};
  var html = '';
  Object.keys(names).forEach(function(r) {
    if (_roleLevels[r] > _currentRoleLevel) return;
    html += '<option value="' + r + '"' + (r === _currentRole ? ' selected' : '') + '>'
      + (r === _currentRole ? 'Same as me (' + names[r] + ')' : names[r]) + '</option>';
  });
  sel.innerHTML = html;
}
function toggleApiKeyForm() {
  fillApiKeyRoles();
  var form = document.getElementById('ak-create-form');
  if (form) form.classList.toggle('hidden');
  var newTok = document.getElementById('ak-new-token');
  if (newTok) newTok.classList.add('hidden');
}
async function createApiKey() {
  var errEl = document.getElementById('ak-error');
  if(errEl) errEl.style.display='none';
  var label = document.getElementById('ak-label').value.trim() || 'API Key';
  var expiryDays = parseInt(document.getElementById('ak-expiry').value) || 90;
  var ips = document.getElementById('ak-ips').value.trim();
  var origins = document.getElementById('ak-origins').value.trim();
  try {
    var r = await api('auth/token', {label: label, expiryDays: expiryDays, allowedIps: ips, allowedOrigins: origins, role: (document.getElementById('ak-role')||{}).value || ''});
    if (r.error) { if(errEl){errEl.textContent=r.error;errEl.style.display='block';} return; }
    document.getElementById('ak-create-form').classList.add('hidden');
    var newEl = document.getElementById('ak-new-token');
    document.getElementById('ak-token-value').textContent = r.token;
    newEl.classList.remove('hidden');
    document.getElementById('ak-label').value = '';
    document.getElementById('ak-ips').value = '';
    document.getElementById('ak-origins').value = '';
    loadApiKeys();
  } catch(e) { if(errEl){errEl.textContent=e.message;errEl.style.display='block';} }
}
function copyApiKey() {
  var tok = document.getElementById('ak-token-value').textContent;
  navigator.clipboard.writeText(tok).then(function(){
    var btn = document.querySelector('#ak-new-token .btn');
    if(btn){btn.textContent='Copied!';setTimeout(function(){btn.textContent='Copy'},1500);}
  });
}
async function loadApiKeys() {
  var el = document.getElementById('ak-list');
  if (!el) return;
  try {
    var r = await api('auth/tokens');
    if (r.error) { el.innerHTML='<p style="color:var(--dim);font-size:12px">'+escHtml(r.error)+'</p>'; return; }
    if (!r.tokens || !r.tokens.length) {
      el.innerHTML='<p style="color:var(--dim);font-size:12px">No active API keys.</p>';
      return;
    }
    var html = '<div style="overflow-x:auto;-webkit-overflow-scrolling:touch">'
      + '<table style="width:100%;font-size:12px;border-collapse:collapse">'
      + '<thead><tr style="border-bottom:1px solid var(--bdr);text-align:left">'
      + '<th style="padding:6px 8px;color:var(--dim);font-weight:600">Label</th>'
      + '<th style="padding:6px 8px;color:var(--dim);font-weight:600">Prefix</th>'
      + '<th style="padding:6px 8px;color:var(--dim);font-weight:600">User</th>'
      + '<th style="padding:6px 8px;color:var(--dim);font-weight:600">Expires</th>'
      + '<th style="padding:6px 8px;color:var(--dim);font-weight:600">Restrictions</th>'
      + '<th style="padding:6px 8px"></th>'
      + '</tr></thead><tbody>';
    r.tokens.forEach(function(t) {
      var expDate = new Date(t.expiry * 1000);
      var daysLeft = Math.ceil((t.expiry*1000 - Date.now()) / 86400000);
      var expColor = daysLeft < 7 ? 'var(--red)' : (daysLeft < 30 ? 'var(--yel)' : 'var(--dim)');
      var restrictions = [];
      if (t.allowedIps && t.allowedIps.length) restrictions.push('IP: ' + t.allowedIps.join(', '));
      if (t.allowedOrigins && t.allowedOrigins.length) restrictions.push('Origin: ' + t.allowedOrigins.join(', '));
      var rStr = restrictions.length ? restrictions.join('; ') : '<span style="color:var(--dim)">none</span>';
      html += '<tr style="border-bottom:1px solid var(--bdr)">'
        + '<td style="padding:6px 8px;font-weight:500">' + escHtml(t.label) + '</td>'
        + '<td style="padding:6px 8px"><code style="font-size:11px">' + escHtml(t.prefix) + '</code></td>'
        + '<td style="padding:6px 8px">' + escHtml(t.user) + ' <span style="color:var(--dim)">(' + t.role + ')</span></td>'
        + '<td style="padding:6px 8px;color:'+expColor+'">' + expDate.toLocaleDateString() + ' <span style="font-size:11px">(' + daysLeft + 'd)</span></td>'
        + '<td style="padding:6px 8px;font-size:11px;max-width:200px;word-break:break-word">' + rStr + '</td>'
        + '<td style="padding:6px 8px"><button class="btn btn-ghost btn-sm" style="color:var(--red);font-size:11px;padding:2px 8px" onclick="revokeApiKey(\''+escHtml(t.prefix.replace('...',''))+'\')">Revoke</button></td>'
        + '</tr>';
    });
    html += '</tbody></table></div>';
    el.innerHTML = html;
  } catch(e) { el.innerHTML='<p style="color:var(--red);font-size:12px">'+escHtml(e.message)+'</p>'; }
}
async function revokeApiKey(prefix) {
  if (!confirm('Revoke API key starting with "'+prefix+'"? This cannot be undone.')) return;
  var r = await api('auth/token/revoke', {prefix: prefix});
  if (r.error) { alert(r.error); return; }
  loadApiKeys();
}

// ── Autohost ────────────────────────────────────────
async function loadAutohost() {
  var r = await api('autohost');
  document.getElementById('ah-enabled').value = r.enabled ? '1' : '0';
  document.getElementById('ah-authorize').value = r.authorize || 'open';
  document.getElementById('ah-dns').value = r.dnsCheck !== false ? '1' : '0';
  document.getElementById('ah-allowlist-row').style.display = r.authorize === 'allowlist' ? '' : 'none';
  var el = document.getElementById('ah-status');
  var prov = r.provisioning || [];
  el.innerHTML = prov.length
    ? '<div class="card" style="margin-bottom:12px"><h3 style="font-size:14px;margin-bottom:8px">Currently Provisioning</h3>' + prov.map(function(h){return '<div>\u23f3 '+escHtml(h)+'</div>';}).join('') + '</div>'
    : '';
  var logEl = document.getElementById('ah-log');
  var lines = r.recentLog || [];
  if (lines.length) {
    logEl.innerHTML = '<div class="card"><h3 style="font-size:14px;margin-bottom:8px">Recent Activity</h3>'
      + '<pre style="font-size:11px;max-height:200px;overflow-y:auto;margin:0;white-space:pre-wrap">' + escHtml(lines.join('\n')) + '</pre></div>';
  } else {
    logEl.innerHTML = '<div class="card"><p style="color:var(--dim)">No autohost activity yet.</p></div>';
  }
  document.getElementById('ah-authorize').onchange = function() {
    document.getElementById('ah-allowlist-row').style.display = this.value === 'allowlist' ? '' : 'none';
  };
}
async function saveAutohost() {
  var data = {
    enabled: document.getElementById('ah-enabled').value === '1',
    authorize: document.getElementById('ah-authorize').value,
    dnsCheck: document.getElementById('ah-dns').value === '1',
    acmeEmail: document.getElementById('ah-email').value.trim()
  };
  if (data.authorize === 'allowlist') {
    data.allowlist = document.getElementById('ah-allowlist').value;
  }
  await api('autohost/toggle', data);
  loadAutohost();
}

// ── Workers ─────────────────────────────────────────
async function loadWorkers() {
  var r = await api('workers');
  var el = document.getElementById('workers-info');
  if (r.mode==='in-process') { el.innerHTML='<div class="card"><p>In-process mode (no pool).</p></div>'; return; }
  function s(l,v){return '<div><div style="font-size:18px;font-weight:700">'+v+'</div><div style="font-size:11px;color:var(--dim)">'+l+'</div></div>';}
  function fmt(b){return b>1048576?(b/1048576).toFixed(1)+' MB':(b/1024).toFixed(0)+' KB';}
  function fmtT(s){s=Number(s)||0;var h=Math.floor(s/3600),m=Math.floor((s%3600)/60);return h?h+'h '+m+'m':m+'m';}
  el.innerHTML='<div class="card"><div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(130px,1fr));gap:12px">'
    +s('Workers',r.workers)+s('Active',r.activeWorkers||0)+s('Requests',(r.totalRequests||0).toLocaleString())
    +s('Memory',fmt(r.memoryUsage||0))+s('Peak',fmt(r.memoryPeak||0))+s('Uptime',fmtT(r.uptime||0))
    +'</div></div>';
  document.getElementById('worker-count').value=r.workers;
  var recEl = document.getElementById('worker-recommendation');
  if (recEl) {
    var m = r.memory;
    function mb(b) { return b >= 1048576 ? (b / 1048576).toFixed(1) + ' MB' : Math.round(b / 1024) + ' KB'; }
    if (m && m.base) {
      var txt = t('{n} workers are forked from a base process of {base}. They share its memory until they change it (copy-on-write).', {n: r.workers, base: mb(m.base)});
      if (m.avgPrivate !== null && m.avgPrivate !== undefined) {
        txt += ' ' + t('Each worker adds on average {each} of its own, so about {total} in all.', {each: mb(m.avgPrivate), total: mb(m.base + m.totalPrivate)});
      } else if (m.avgRss) {
        txt += ' ' + t('Each worker\u2019s resident size averages {each}, most of it shared with the base; this system cannot tell how much is private.', {each: mb(m.avgRss)});
      }
      recEl.textContent = txt;
    } else {
      recEl.textContent = t('{n} workers running.', {n: r.workers});
    }
  }
  // Load worker detail
  var d = await api('workers/detail');
  var detailEl = document.getElementById('worker-detail');
  if (detailEl && d.workers) {
    var tbl = '<table style="width:100%;font-size:12px;border-collapse:collapse"><tr style="color:var(--dim)">'
      + '<th style="text-align:left;padding:4px">PID</th><th>Status</th><th>Requests</th><th></th></tr>';
    d.workers.forEach(function(w) {
      var status = w.busy ? '<span style="color:var(--yel)">\u25cf busy</span>'
        : w.recycleAfter ? '<span style="color:var(--red)">\u21bb recycling</span>'
        : '<span style="color:var(--grn)">\u25cf idle</span>';
      tbl += '<tr style="border-top:1px solid var(--border);padding:4px"><td style="padding:4px">' + w.pid + '</td><td style="text-align:center">' + status
        + '</td><td style="text-align:center">' + (w.requests||0)
        + '</td><td style="text-align:right"><button class="btn btn-ghost" style="font-size:10px;padding:2px 6px" onclick="recycleWorker(' + w.index + ')">\u21bb</button></td></tr>';
    });
    tbl += '</table>';
    detailEl.innerHTML = '<div class="card" style="margin-top:12px"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px">'
      + '<h3 style="font-size:14px;margin:0">Worker Detail</h3>'
      + '<button class="btn btn-primary" style="font-size:11px;padding:4px 10px" onclick="recycleAll()">Recycle All</button></div>'
      + '<p style="font-size:11px;color:var(--dim);margin:0 0 8px">Mode: ' + d.mode + ' \u00b7 Max requests: ' + d.maxRequests + ' \u00b7 Queue: ' + (d.pending||0) + '</p>'
      + tbl + '</div>';
  }
}
async function resizeWorkers() {
  var c=parseInt(document.getElementById('worker-count').value);
  if(!c||c<1)return alert('Enter a number');
  var r=await api('workers/resize',{workers:c});
  alert(r.error||'Resizing to '+c); loadWorkers();
}
async function recycleWorker(idx) {
  var r = await api('workers/recycle', {index: idx});
  loadWorkers();
}
async function recycleAll() {
  if (!confirm('Recycle all workers? Busy workers finish their current request first.')) return;
  var r = await api('workers/recycle', {});
  alert('Recycled: ' + (r.recycled ? r.recycled.immediate + ' immediate, ' + r.recycled.pending + ' pending' : 'done'));
  loadWorkers();
}

// ── Logs ────────────────────────────────────────────
async function loadLogs(type) {
  type=type||'access';
  var lines=document.getElementById('log-lines').value;
  // Highlight active log button
  var accBtn = document.getElementById('log-btn-access');
  var errBtn = document.getElementById('log-btn-error');
  if (accBtn) { accBtn.className = type==='access' ? 'btn btn-primary' : 'btn btn-ghost'; }
  if (errBtn) { errBtn.className = type==='error' ? 'btn btn-primary' : 'btn btn-ghost'; }
  // Hide the app log file tree when viewing server logs
  var tree = document.getElementById('log-file-tree');
  if (tree) tree.classList.add('hidden');
  var r=await api('logs?type='+type+'&lines='+lines);
  var el=document.getElementById('logs-output');
  if(r.disabled){el.textContent=r.message||'Logging disabled';return;}
  if(!r.exists){el.textContent='Log file not found: '+r.file+'\nLogging may not be configured. Ensure Q.webserver.log.dir is set in config.';return;}
  el.textContent=r.lines.join('\n');
  el.scrollTop=el.scrollHeight;
}
async function loadLogStatus() {
  var r=await api('logs/status');
  var cb=document.getElementById('log-access-enabled');
  if(cb)cb.checked=r.accessEnabled!==false;
}
async function toggleAccessLog(enabled) {
  var r=await api('logs/toggle',{access:!!enabled});
  if(r.error){alert(r.error);return;}
  loadLogs('access');
}
async function loadAppLogFiles(dirName) {
  var tree = document.getElementById('log-file-tree');
  var out = document.getElementById('logs-output');
  if (!dirName) { if(tree)tree.classList.add('hidden'); return; }
  if(tree)tree.classList.remove('hidden');
  tree.innerHTML = '<p style="color:var(--dim);font-size:12px">Loading\u2026</p>';
  var r = await api('apps/logs?app='+encodeURIComponent(dirName));
  if (r.error) { tree.innerHTML='<p style="color:var(--red);font-size:12px">'+escHtml(r.error)+'</p>'; return; }
  if (!r.files || !r.files.length) {
    tree.innerHTML='<p style="color:var(--dim);font-size:12px">No log files found.</p>';
    return;
  }
  tree.innerHTML = r.files.map(function(f){
    return '<div class="log-file" onclick="viewAppLog(\''+dirName+'\',\''+f.path.replace(/\\/g,'\\\\').replace(/'/g,"\\'")+'\',this)">'
      + '<span>\uD83D\uDCC4</span><span style="flex:1">'+escHtml(f.path)+'</span><span class="log-size">'+fmtBytes(f.size)+'</span></div>';
  }).join('');
}
async function viewAppLog(dirName, filePath, el) {
  if (el) {
    el.parentNode.querySelectorAll('.log-file').forEach(function(f){f.classList.remove('active')});
    el.classList.add('active');
  }
  var out = document.getElementById('logs-output');
  out.textContent = 'Loading\u2026';
  var lines = document.getElementById('log-lines').value;
  var r = await api('apps/logs?app='+encodeURIComponent(dirName)+'&file='+encodeURIComponent(filePath)+'&lines='+lines);
  if (!r.exists) { out.textContent = 'Log file not found'; return; }
  out.textContent = r.lines.join('\n');
  out.scrollTop = out.scrollHeight;
}

// ── Cron ────────────────────────────────────────────
async function loadCron() {
  var r=await api('cron');
  var el=document.getElementById('cron-list');
  if(!r.tasks||!r.tasks.length){el.innerHTML='<div class="card"><p style="color:var(--dim)">No scheduled tasks configured. Click "+ Add Task" to create one.</p></div>';return;}
  el.innerHTML=r.tasks.map(function(t){
    var sched=t.every?formatInterval(t.every):t.times?t.times.join(', '):'manual';
    if(t.weekdays&&t.weekdays.length)sched+=' ('+t.weekdays.join(', ')+')';
    if(t.monthdays&&t.monthdays.length)sched+=' [days: '+t.monthdays.join(', ')+']';
    var tn=t.name.replace(/\\/g,'\\\\').replace(/'/g,"\\'");
    var isPanel=t.source==='panel';
    var opacity=t.disabled?'opacity:.5':'';
    var badge=t.disabled?'<span style="background:var(--red);color:#fff;font-size:10px;padding:1px 6px;border-radius:8px;margin-left:6px">disabled</span>':'';
    var builtinBadge=!isPanel?'<span style="background:rgba(124,92,252,.15);color:var(--ac);font-size:10px;padding:1px 6px;border-radius:8px;margin-left:6px">config</span>':'';
    return '<div class="card" style="margin-bottom:8px;'+opacity+'">'
      +'<div style="display:flex;justify-content:space-between;align-items:flex-start">'
      +'<div><strong>'+escHtml(t.name)+'</strong>'+badge+builtinBadge
      +'<div style="font-size:11px;color:var(--dim);margin-top:2px">'+escHtml(t.handler)+' · '+escHtml(sched)+'</div></div>'
      +'<div style="display:flex;gap:4px;flex-shrink:0">'
      +'<button class="btn btn-ghost" style="font-size:11px;padding:4px 10px" onclick="toggleCronTask(\''+tn+'\','+(!t.disabled)+')">'+(t.disabled?'Enable':'Disable')+'</button>'
      +(isPanel?'<button class="btn btn-ghost" style="font-size:11px;padding:4px 10px" onclick="editCronTask(\''+tn+'\')">Edit</button>':'')
      +'<button class="btn btn-ghost" style="font-size:11px;padding:4px 10px" onclick="runCron(\''+tn+'\')">Run Now</button>'
      +(isPanel?'<button class="btn btn-ghost" style="font-size:11px;padding:4px 10px;color:var(--red)" onclick="removeCronTask(\''+tn+'\')">Delete</button>':'')
      +'</div></div></div>';
  }).join('');
}
function formatInterval(s){
  if(s>=86400){var d=Math.round(s/86400);return d+(d===1?' day':' days');}
  if(s>=3600){var h=Math.round(s/3600);return h+(h===1?' hour':' hours');}
  if(s>=60){var m=Math.round(s/60);return m+(m===1?' minute':' minutes');}
  return s+(s===1?' second':' seconds');
}
function showCronForm(edit){
  document.getElementById('cron-form').classList.remove('hidden');
  document.getElementById('cron-form-title').textContent=edit?'Edit Scheduled Task':'Add Scheduled Task';
  document.getElementById('cron-form-error').style.display='none';
  if(!edit){
    document.getElementById('cron-edit-orig').value='';
    document.getElementById('cron-name').value='';
    document.getElementById('cron-handler').value='';
    document.getElementById('cron-sched-type').value='interval';
    document.getElementById('cron-every').value='3600';
    document.getElementById('cron-times').value='';
    document.getElementById('cron-monthdays').value='';
    document.querySelectorAll('#cron-weekdays input').forEach(function(c){c.checked=false;});
    toggleCronSchedFields();
  }
}
function hideCronForm(){document.getElementById('cron-form').classList.add('hidden');}
function toggleCronSchedFields(){
  var t=document.getElementById('cron-sched-type').value;
  document.getElementById('cron-interval-fields').style.display=t==='interval'?'':'none';
  document.getElementById('cron-times-fields').style.display=t==='times'?'':'none';
}
async function editCronTask(name){
  var r=await api('cron');
  var t=r.tasks.find(function(x){return x.name===name;});
  if(!t)return;
  showCronForm(true);
  document.getElementById('cron-edit-orig').value=name;
  document.getElementById('cron-name').value=t.name;
  document.getElementById('cron-handler').value=t.handler||'';
  if(t.every){
    document.getElementById('cron-sched-type').value='interval';
    document.getElementById('cron-every').value=t.every;
  } else {
    document.getElementById('cron-sched-type').value='times';
    document.getElementById('cron-times').value=(t.times||[]).join(', ');
    document.getElementById('cron-monthdays').value=(t.monthdays||[]).join(', ');
    document.querySelectorAll('#cron-weekdays input').forEach(function(c){
      c.checked=(t.weekdays||[]).indexOf(c.value)!==-1;
    });
  }
  toggleCronSchedFields();
}
async function saveCronTask(){
  var errEl=document.getElementById('cron-form-error');
  errEl.style.display='none';
  var schedType=document.getElementById('cron-sched-type').value;
  var payload={
    name:document.getElementById('cron-name').value.trim(),
    handler:document.getElementById('cron-handler').value.trim(),
    schedType:schedType
  };
  if(schedType==='interval'){
    payload.every=parseInt(document.getElementById('cron-every').value)||0;
  } else {
    payload.times=document.getElementById('cron-times').value.split(',').map(function(s){return s.trim();}).filter(Boolean);
    var wd=[];
    document.querySelectorAll('#cron-weekdays input:checked').forEach(function(c){wd.push(c.value);});
    if(wd.length)payload.weekdays=wd;
    var md=document.getElementById('cron-monthdays').value.trim();
    if(md)payload.monthdays=md.split(',').map(function(s){return parseInt(s.trim());}).filter(function(n){return n>0;});
  }
  var origName=document.getElementById('cron-edit-orig').value;
  var route,body;
  if(origName){
    route='cron/update';
    payload.origName=origName;
  } else {
    route='cron/add';
  }
  var r=await api(route,payload);
  if(r.error){errEl.textContent=r.error;errEl.style.display='';return;}
  hideCronForm();
  loadCron();
}
async function removeCronTask(name){
  if(!confirm('Delete task "'+name+'"? This cannot be undone.'))return;
  var r=await api('cron/remove',{name:name});
  if(r.error){alert(r.error);return;}
  loadCron();
}
async function toggleCronTask(name,disabled){
  var r=await api('cron/toggle',{name:name,disabled:disabled});
  if(r.error){alert(r.error);return;}
  loadCron();
}
async function runCron(n){var r=await api('cron/run',{task:n});alert(r.error||'Dispatched '+n);}

